CardSets.register({"id":"cats","name":"Cats","code":"CAT","description":"383 cards celebrating the domestic cat — 83 breeds, 42 coats and colours, 52 famous cats, plus the history, art, mythology, anatomy, behaviour, working lives and beloved places of the world's favourite animal.","theme":{"primary":"#e07a3f","secondary":"#43302e","artBackground":"#f7ead9","artFit":"cover"},"pack":{"name":"Cats Pack","emblem":"🐱","skin":"cats","slots":[{"count":5,"label":"Common","odds":{"common":100}},{"count":2,"label":"Uncommon","odds":{"uncommon":100}},{"count":1,"label":"Wild card","odds":{"common":55,"uncommon":30,"rare":12,"epic":3}},{"count":1,"label":"Rare or better (guaranteed)","odds":{"rare":81.8,"epic":14,"legendary":4,"chase":0.2}}]},"cards":[{"name":"Maine Coon","rarity":"chase","id":"maine-coon","subtitle":"Breed","details":"America's largest domestic breed: a shaggy, tufted farm cat from Maine with a long plumed tail and a chirping voice.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Karin%20Maine%20Coon.jpg?width=1024"},{"name":"Siamese","rarity":"chase","id":"siamese","subtitle":"Breed","details":"Thailand's pointed temple cat: blue almond eyes, a loud conversational voice, and a lifelong devotion to its people.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Siamese%20cat%2C%20chocolate%20point.jpg?width=1024"},{"name":"Tabby","rarity":"chase","id":"tabby","subtitle":"Pattern","details":"Not a breed but the wild-type coat: stripes, swirls, spots, or ticks, and an M-shaped mark on the forehead.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tabby_cat_from_Kuwait_03.jpg?width=1024"},{"name":"Grumpy Cat","rarity":"chase","id":"grumpy-cat","subtitle":"Famous Cat","details":"Tardar Sauce, whose feline dwarfism gave the internet its favourite permanent frown and a thousand memes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Grumpy%20Cat%20%2814349262900%29.jpg?width=1024"},{"name":"Garfield","rarity":"chase","id":"garfield","subtitle":"Famous Cat","details":"Jim Davis's lasagna-loving, Monday-hating orange tabby, in comics since 1978 and syndicated around the world.","image":"https://twoworldstreasures.com/wp-content/uploads/2024/01/garfield.jpg"},{"name":"Hello Kitty","rarity":"chase","id":"hello-kitty","subtitle":"Famous Cat","details":"Sanrio's bow-wearing icon, debuting in 1974 on a coin purse and becoming one of media's biggest franchises.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hello%20Kitty%20and%20Friends%20Cafe%20(Universal%20CityWalk).jpg?width=600"},{"name":"Felicette","rarity":"chase","id":"felicette","subtitle":"History","details":"The first and only cat in space, launched by France in 1963 and recovered safely after her suborbital flight.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/F%C3%A9licette%20et%20Bigoudis.jpg?width=1024"},{"name":"Schrodinger's Cat","rarity":"chase","id":"schrodingers-cat","subtitle":"History","details":"Erwin Schrodinger's 1935 thought experiment: a cat in a box, both alive and dead until observed, illustrating quantum ideas.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Schrodinger%20cat%20in%20box.jpg?width=500"},{"name":"Bastet","rarity":"chase","id":"bastet","subtitle":"Mythology","details":"Egypt's beloved cat goddess of home, music, and protection, honoured at Bubastis with festivals drawing hundreds of thousands.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Figurine%20of%20the%20Goddess%20Bastet%20as%20a%20Cat%20LACMA%20AC1992.152.50.jpg?width=1024"},{"name":"Maneki-neko","rarity":"chase","id":"maneki-neko","subtitle":"Mythology","details":"Japan's beckoning cat, one paw raised to invite luck and customers; a raised left paw calls people, the right calls money.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Maneki-neko-ja.jpg?width=1024"},{"name":"Persian","rarity":"legendary","id":"persian","subtitle":"Breed","details":"The long-haired aristocrat of the cat world, prized for a flowing coat, round face, and calm, dignified manner.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chocolate%20Persian.jpg?width=1024"},{"name":"British Shorthair","rarity":"legendary","id":"british-shorthair","subtitle":"Breed","details":"A plush blue-grey teddy bear of a cat, descended from Roman-era British farm cats and famously unflappable.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20170604%20kot%20na%20wystawie%20w%20Krakowie%207971.jpg?width=1024"},{"name":"Ragdoll","rarity":"legendary","id":"ragdoll","subtitle":"Breed","details":"A large, blue-eyed Californian breed named for going blissfully limp and floppy when picked up and cuddled.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ragdoll%20Cat%20Stretching.jpg?width=1024"},{"name":"Bengal","rarity":"legendary","id":"bengal","subtitle":"Breed","details":"A domestic cat in a wild coat: bred from Asian leopard cat crosses, with glittered rosettes and an athlete's build.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BEN%20Bengalian%20kitten%20%284492540155%29.jpg?width=1024"},{"name":"Sphynx","rarity":"legendary","id":"sphynx","subtitle":"Breed","details":"The hairless Canadian wonder: warm, suede-soft skin, huge ears, and an extrovert's hunger for laps and sweaters.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1%20adult%20cat%20Sphynx.%20img%20047.jpg?width=1024"},{"name":"Norwegian Forest Cat","rarity":"legendary","id":"norwegian-forest-cat","subtitle":"Breed","details":"The Vikings' ship cat grown large: a waterproof double coat, lynx-tipped ears, and expert climbing claws.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Norwegian%20Forest%20Cat%20in%20snow.jpg?width=1024"},{"name":"Tortoiseshell","rarity":"legendary","id":"tortoiseshell","subtitle":"Pattern","details":"A mottled patchwork of black and orange worn almost entirely by females; owners swear by the tortitude.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kira%2C_a_tortoise_shell_cat.jpg?width=1024"},{"name":"Calico","rarity":"legendary","id":"calico","subtitle":"Pattern","details":"A white cat splashed with orange and black patches; in Japan, the pattern of the lucky beckoning cat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Calico_cat%2C_-_Assisi%2C_Italy.jpg?width=1024"},{"name":"Tuxedo","rarity":"legendary","id":"tuxedo","subtitle":"Pattern","details":"A black cat in formal wear: white chest, belly, and paws, dressed for an evening that never ends.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yellow-eyed%20resting%20tuxedo%20cat.jpg?width=1024"},{"name":"Lil Bub","rarity":"legendary","id":"lil-bub","subtitle":"Famous Cat","details":"A tiny perma-kitten with extra toes and no teeth, whose sweet face raised fortunes for special-needs pets.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3b/Lil-Bub-2013.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Maru","rarity":"legendary","id":"maru","subtitle":"Famous Cat","details":"Japan's box-obsessed Scottish Fold, whose sliding dives into ever-smaller boxes drew hundreds of millions of views.","image":"https://www.guinnessworldrecords.jp/news/2017/3/images/maru-466616.jpg"},{"name":"Colonel Meow","rarity":"legendary","id":"colonel-meow","subtitle":"Famous Cat","details":"A Himalayan-Persian with a record nine-inch coat and a world-domination glare worthy of his rank.","image":"https://khpt.1cdn.vn/2013/09/01/www.khoahocphothong.com.vn-vnt_upload-news-09_2013-_w17_00e35.jpg"},{"name":"Nyan Cat","rarity":"legendary","id":"nyan-cat","subtitle":"Famous Cat","details":"A pixel cat with a Pop-Tart body flying through space on a rainbow, the defining GIF of the early meme age.","image":"https://articles-img.sftcdn.net/t_article_cover_xl/auto-mapping-folder/sites/3/2019/02/Nyan-Cat-e1549325604960.jpg"},{"name":"Mrs. Chippy","rarity":"legendary","id":"mrs-chippy","subtitle":"History","details":"The Endurance expedition's beloved tabby, who walked the ship's rails through Antarctic ice with Shackleton's crew.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mrschippy.jpg?width=1024"},{"name":"Trim","rarity":"legendary","id":"trim","subtitle":"History","details":"Matthew Flinders' ship cat, who circumnavigated Australia and survived shipwreck and imprisonment beside his captain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Statue%20of%20Trim%20the%20cat%20Mitchell%20Library%2021092012.jpg?width=1024"},{"name":"Simon of HMS Amethyst","rarity":"legendary","id":"simon-of-hms-amethyst","subtitle":"History","details":"Wounded in the 1949 Yangtze incident, this ship's cat kept hunting rats and received the Dickin Medal.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Able%20Seacat%20Simon.jpg?width=1024"},{"name":"Le Chat Noir Poster","rarity":"legendary","id":"le-chat-noir-poster","subtitle":"Art","details":"Theophile Steinlen's 1896 poster for the Paris cabaret: a haughty black cat who became Montmartre's emblem.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Th%C3%A9ophile%20Alexandre%20Steinlen%20-%20Tourn%C3%A9e%20du%20Chat%20Noir%20-%20Google%20Art%20Project.jpg?width=500"},{"name":"Louis Wain's Cats","rarity":"legendary","id":"louis-wains-cats","subtitle":"Art","details":"The English artist whose dressed, dancing cats defined the Edwardian cat craze and filled a nation's postcards.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%27Charlie%27%20Morton%27s%20Mascot%20%E2%80%93%20The%20Persian%20Cat%20of%20the%20Palace%20Theatre%20by%20Louis%20Wain%20%281860%E2%80%931939%29.png?width=1024"},{"name":"Freyja's Chariot Cats","rarity":"legendary","id":"freyjas-chariot-cats","subtitle":"Mythology","details":"Norse goddess Freyja's chariot is pulled by two great cats, Bygul and Trjegul, gifts bound to love and the harvest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Freyja%20riding%20with%20her%20cats%20%281874%29.jpg?width=1024"},{"name":"Bakeneko","rarity":"legendary","id":"bakeneko","subtitle":"Mythology","details":"Japan's monster cat: an aged house cat whose tail forks and who walks upright, haunts households, and dances with towels.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Buson%20Bakeneko.jpg?width=1024"},{"name":"Sandpaper Tongue","rarity":"legendary","id":"sandpaper-tongue","subtitle":"Anatomy","details":"A cat's tongue is armoured with hundreds of tiny backward hooks called papillae, built for grooming and stripping meat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20tongue%20macro.jpg?width=1024"},{"name":"Purring","rarity":"legendary","id":"purring","subtitle":"Behavior","details":"Cats purr when content, frightened, in pain, and in labour; the frequency is even linked in studies to bone healing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20231125%20housecat%20south%20meadows%20PD100306.jpg?width=1024"},{"name":"Tama the Stationmaster","rarity":"legendary","id":"tama-the-stationmaster","subtitle":"Working Cat","details":"A calico appointed stationmaster of Kishi station in 2007, whose presence revived a failing railway and a town.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stationmaster%20NITAMA%20and%20TAMA%2020110105.jpg?width=1024"},{"name":"Larry, Chief Mouser","rarity":"legendary","id":"larry-chief-mouser","subtitle":"Working Cat","details":"Chief Mouser to the Cabinet Office at 10 Downing Street since 2011, a Battersea rescue with an official title.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Larry%20Chief%20Mouser.jpg?width=1024"},{"name":"Towser the Distillery Cat","rarity":"legendary","id":"towser-the-distillery-cat","subtitle":"Working Cat","details":"Glenturret distillery's legendary mouser, credited with 28,899 mice and honoured with a bronze statue.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Towser%20Memorial%2C%20Glenturret%20Distillery%20Visitors%20Centre%20-%20geograph.org.uk%20-%204001.jpg?width=1024"},{"name":"Tashirojima Cat Island","rarity":"legendary","id":"tashirojima-cat-island","subtitle":"Cat Place","details":"A Japanese island where cats outnumber people, fishing luck is feline, and a cat shrine stands in the village.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%E7%94%B0%E4%BB%A3%E5%B3%B6%E3%81%AE%E7%8C%AB%20%EF%BC%88Cats%20in%20Tashiro%20island%EF%BC%892013%20001.jpg?width=1024"},{"name":"Aoshima Cat Island","rarity":"legendary","id":"aoshima-cat-island","subtitle":"Cat Place","details":"One of Japan's most famous cat islands, where over a hundred cats rule a village of a handful of residents.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cats%20in%20aoshima%20island%201.JPG?width=1024"},{"name":"Russian Blue","rarity":"epic","id":"russian-blue","subtitle":"Breed","details":"A silvery-blue Archangel cat with emerald eyes and a reserved, gentle loyalty to one chosen household.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Male%20Russian%20Blue%20cat%20at%20the%202011%20Moscow%20Cat%20Show%20%285624853840%29.jpg?width=1024"},{"name":"Abyssinian","rarity":"epic","id":"abyssinian","subtitle":"Breed","details":"One of the oldest breeds: a ticked, athletic Ethiopian-style cat that treats every room as a jungle gym.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Abyssinian%20cat%20-%20Patricia.jpg?width=1024"},{"name":"Scottish Fold","rarity":"epic","id":"scottish-fold","subtitle":"Breed","details":"A Scottish farm cat whose folded ears and round owl-like face come from a natural cartilage mutation.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Scottish-Fold-Cat.jpg?width=1024"},{"name":"Birman","rarity":"epic","id":"birman","subtitle":"Breed","details":"The Sacred Cat of Burma: silky, pointed, blue-eyed, and born wearing four neat white gloves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Birman%20cat%20%2851707197922%29.jpg?width=1024"},{"name":"Burmese","rarity":"epic","id":"burmese","subtitle":"Breed","details":"A compact, people-obsessed breed descended from Wong Mau, a single walnut-brown cat brought from Burma in 1930.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BurMau%20Vega%20Star%2C%20champagne%20burmese%20kitten%20%28cropped%29.jpg?width=1024"},{"name":"Turkish Angora","rarity":"epic","id":"turkish-angora","subtitle":"Breed","details":"An ancient, graceful Turkish breed with a silky single coat, plumed tail, and a fondness for high perches.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Turkish%20Angora%20Odd-Eyed.jpg?width=1024"},{"name":"Egyptian Mau","rarity":"epic","id":"egyptian-mau","subtitle":"Breed","details":"The only naturally spotted domestic breed, descended from Egyptian cats and fast enough to outrun most cats alive.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Egyptian%20Mau%20Bronze.jpg?width=1024"},{"name":"Siberian","rarity":"epic","id":"siberian","subtitle":"Breed","details":"Russia's national cat: a hearty, triple-coated forest breed famed for dog-like loyalty and a powerful leap.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/May%20cat.JPG?width=1024"},{"name":"Black Cat","rarity":"epic","id":"black-cat","subtitle":"Pattern","details":"Solid black from root to tip, thanks to a dominant gene; in many traditions a sign of luck, not doom.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black%20cat%20portraits.jpg?width=1024"},{"name":"Classic Tabby","rarity":"epic","id":"classic-tabby","subtitle":"Pattern","details":"The blotched tabby: bold swirls and a bullseye target on each flank, like marble cake in fur.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Siberian_black_tabby_blotched_cat_03.jpg?width=1024"},{"name":"Mackerel Tabby","rarity":"epic","id":"mackerel-tabby","subtitle":"Pattern","details":"The tiger cat: narrow vertical stripes running down from a dark spine line, the commonest tabby of all.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat_November_2010-1a.jpg?width=1024"},{"name":"Spotted Tabby","rarity":"epic","id":"spotted-tabby","subtitle":"Pattern","details":"A mackerel pattern broken into spots, the look of Bengals, Ocicats, and Egyptian Maus.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oriental%20shorthair%2C%20black%20spotted%20tabby.jpg?width=1024"},{"name":"Ticked Tabby","rarity":"epic","id":"ticked-tabby","subtitle":"Pattern","details":"Each hair banded light and dark with no body stripes at all, giving Abyssinians their warm, flecked glow.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Yin_and_Yang.jpg?width=1024"},{"name":"Keyboard Cat","rarity":"epic","id":"keyboard-cat","subtitle":"Famous Cat","details":"Fatso, filmed in 1984 in a blue shirt playing a keyboard; the clip became the internet's playful sign-off.","image":"https://yt3.googleusercontent.com/ytc/AIdro_msfna2anNTOztMPAFlgE09DfyPNjHh_6wiLbsrFA-pvg=s900-c-k-c0x00ffffff-no-rj"},{"name":"The Cat in the Hat","rarity":"epic","id":"the-cat-in-the-hat","subtitle":"Famous Cat","details":"Dr. Seuss's tall-hatted chaos agent, who arrived on a rainy day in 1957 and rewired children's books forever.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/Cat_in_the_Hat_121014-F-SI013-166.jpg/1280px-Cat_in_the_Hat_121014-F-SI013-166.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Puss in Boots","rarity":"epic","id":"puss-in-boots","subtitle":"Famous Cat","details":"The fairy tale's smooth-talking strategist in fine boots, winning his master a fortune by sheer confidence.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Maxfield_Parrish_-_Puss-in-Boots_%281913%29.jpg/1280px-Maxfield_Parrish_-_Puss-in-Boots_%281913%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Felix the Cat","rarity":"epic","id":"felix-the-cat","subtitle":"Famous Cat","details":"The silent-film-era star with a magic bag of tricks, one of the first cartoon characters to become a merch empire.","image":"https://upload.wikimedia.org/wikipedia/commons/8/8a/Felix-the-Cat-poster.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Tom","rarity":"epic","id":"tom","subtitle":"Famous Cat","details":"The ever-scheming half of Tom and Jerry, chasing one mouse through decades of cartoon mayhem since 1940.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7d/TOM_%26_JERRY_NAJBOLJI_PRIJATELJI_STARI_PLAKAT.webp?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Sylvester","rarity":"epic","id":"sylvester","subtitle":"Famous Cat","details":"Warner Bros.' lisping black-and-white hunter, forever one scheme away from finally catching Tweety.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6d/2010-96-1_Plaque%2C_Ship%2C_USS_Alameda_County%2C_AVB-1_%285062505993%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Unsinkable Sam","rarity":"epic","id":"unsinkable-sam","subtitle":"History","details":"A ship's cat said to have survived the sinking of three warships in 1941, retiring to a sailors' home in Belfast.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oscar%2C%20cat%20from%20the%20German%20ship%20%27Bismarck%27.jpg?width=1024"},{"name":"Faith the Church Cat","rarity":"epic","id":"faith-the-church-cat","subtitle":"History","details":"A London church cat who sheltered her kitten through the Blitz; both survived a direct hit on the church in 1940.","image":"https://lovecatsworld.com/wp-content/uploads/2021/11/FAITH-HERO-CAT-LONDON.png"},{"name":"Pooli","rarity":"epic","id":"pooli","subtitle":"History","details":"An American attack transport's cat who served through Pacific campaigns and was awarded ribbons of her own.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pooli%20%28cat%29.jpg?width=1024"},{"name":"Crimean Tom","rarity":"epic","id":"crimean-tom","subtitle":"History","details":"A Sevastopol cat who led British soldiers to hidden Russian food stores during the Crimean War's siege winter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crimean%20Tom.jpg?width=1024"},{"name":"Warhol's Sam Cats","rarity":"epic","id":"warhols-sam-cats","subtitle":"Art","details":"Before the soup cans, Andy Warhol kept some 25 Siamese cats, nearly all named Sam, and published a book of them.","image":"https://chairish-prod.freetls.fastly.net/image/product/sized/d370ee11-abc1-4c82-a77c-22dea10c146e/andy-warhol-estate-25-cats-name-sam-and-one-blue-pussy-holy-cats-by-andy-warhols-mother-vintage-1987-first-edition-slipcase-two-books-set-6724?aspect=fit&width=1200&height=1200"},{"name":"Klee's Cat and Bird","rarity":"epic","id":"klees-cat-and-bird","subtitle":"Art","details":"Paul Klee's 1928 painting of a cat with a tiny bird perched, literally, on its mind.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Klee%20Paul%20Cat%20and%20Bird.jpg?width=1024"},{"name":"Kuniyoshi's Cats","rarity":"epic","id":"kuniyoshis-cats","subtitle":"Art","details":"The Japanese print master Utagawa Kuniyoshi adored cats, filling woodblocks with them and keeping studio cats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20cat%20dressed%20as%20a%20woman%20tapping%20the%20head%20of%20an%20octopus.jpg?width=500"},{"name":"Li Shou","rarity":"epic","id":"li-shou","subtitle":"Mythology","details":"A Chinese cat goddess honoured by farmers for guarding crops from rats; legend says the gods first offered her rule of the world.","image":"https://i0.wp.com/miaoumeme.com/wp-content/uploads/2024/04/DeesseLiShouChats1234567890.jpg?w=560"},{"name":"Nekomata","rarity":"epic","id":"nekomata","subtitle":"Mythology","details":"The split-tailed elder of Japanese cat spirits, said to speak, shapeshift, and stir the dead in old tales.","image":"https://www.dailyartmagazine.com/wp-content/uploads/2024/09/76d05d1931332dda37c03b68275294fa.jpg"},{"name":"Cait Sith","rarity":"epic","id":"cait-sith","subtitle":"Mythology","details":"The fairy cat of Celtic lore, black with a white chest spot, who steals souls and blesses houses that leave out milk.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Page%20158%20illustration%20in%20More%20English%20Fairy%20Tales.png?width=1024"},{"name":"Whiskers","rarity":"epic","id":"whiskers","subtitle":"Anatomy","details":"Vibrissae are deep-rooted sense organs that read air currents, letting a cat navigate and judge gaps in the dark.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brown_tabby_cat_portrait_close_up_02.jpg?width=1024"},{"name":"Tapetum Lucidum","rarity":"epic","id":"tapetum-lucidum","subtitle":"Anatomy","details":"A mirror layer behind the retina bounces light back through the eye, giving cats their glow and superb night sight.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black_cat_in_the_dark.jpg?width=1024"},{"name":"Vertical Pupils","rarity":"epic","id":"vertical-pupils","subtitle":"Anatomy","details":"Slit pupils open and close like camera apertures, giving ambush hunters precise depth judgement in any light.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cute_Cat_with_Beautiful_Green_Eyes.png?width=500"},{"name":"Kneading","rarity":"epic","id":"kneading","subtitle":"Behavior","details":"Making biscuits: kittens knead to encourage milk, and adults keep the habit as a gesture of deep contentment.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20kneading%20and%20sucking%20blanket%201.jpg?width=1024"},{"name":"The Slow Blink","rarity":"epic","id":"the-slow-blink","subtitle":"Behavior","details":"A slow, deliberate blink is cat language for trust; studies show cats slow-blink back at humans who start it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gray%20and%20white%20cat%2C%20eyes%20half-closed.JPG?width=1024"},{"name":"Cat Loaf","rarity":"epic","id":"cat-loaf","subtitle":"Behavior","details":"Paws and tail tucked entirely away, a loafing cat is warm, relaxed, and in no hurry to be anywhere else.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cute%20cat%20in%20loaf%20position.jpg?width=1024"},{"name":"Dewey Readmore Books","rarity":"epic","id":"dewey-readmore-books","subtitle":"Working Cat","details":"Found in an Iowa library book drop in 1988, Dewey became the world's most famous library cat for 19 years.","image":"https://upload.wikimedia.org/wikipedia/en/7/74/Dewey_Readmore_Books.jpg"},{"name":"Felix the Station Cat","rarity":"epic","id":"felix-the-station-cat","subtitle":"Working Cat","details":"Huddersfield station's senior pest controller, with her own cat flap on the platform and a book to her name.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Felix%20the%20station%20cat.jpg?width=1024"},{"name":"Browser the Library Cat","rarity":"epic","id":"browser-the-library-cat","subtitle":"Working Cat","details":"A Texas library cat whose brief eviction by city council in 2016 drew worldwide protest until he was reinstated.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Browser%20White%20Settlement%20Library%20cat.jpg?width=1024"},{"name":"Istanbul, City of Cats","rarity":"epic","id":"istanbul-city-of-cats","subtitle":"Cat Place","details":"Hundreds of thousands of street cats share Istanbul, fed and sheltered by residents as honoured fellow citizens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20near%20Kabata%C5%9F%20in%20Istanbul%2C%2020260605%201734%201298.jpg?width=1024"},{"name":"The Hemingway Home","rarity":"epic","id":"the-hemingway-home","subtitle":"Cat Place","details":"Some sixty polydactyl cats, many named for movie stars, roam Hemingway's Key West house and gardens.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hemingway%20House%20six%20toed%20cat.jpg?width=1024"},{"name":"Himalayan","rarity":"rare","id":"himalayan","subtitle":"Breed","details":"A Persian in Siamese dress: long flowing fur, a flat face, and vivid blue pointed markings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Himalayan%20Cat.jpg?width=1024"},{"name":"Exotic Shorthair","rarity":"rare","id":"exotic-shorthair","subtitle":"Breed","details":"The lazy keeper's Persian: all the round-faced charm of a Persian in a short, plush, low-maintenance coat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bissel%203.jpg?width=1024"},{"name":"Devon Rex","rarity":"rare","id":"devon-rex","subtitle":"Breed","details":"The pixie cat: huge ears, elfin cheekbones, and a soft wavy coat that sheds far less than most.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Devon%20Rex%20Izzy.jpg?width=1024"},{"name":"Cornish Rex","rarity":"rare","id":"cornish-rex","subtitle":"Breed","details":"A Cornish farm kitten grew a coat of pure velvet waves; the breed has no outer guard hairs at all.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20170604%20kot%20wystawa%20Krak%C3%B3w%208006.jpg?width=1024"},{"name":"Tonkinese","rarity":"rare","id":"tonkinese","subtitle":"Breed","details":"A Siamese-Burmese blend with aqua eyes, mixing the chat of one parent with the cuddles of the other.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tonkinese%20Cat.jpg?width=1024"},{"name":"Ocicat","rarity":"rare","id":"ocicat","subtitle":"Breed","details":"Looks like a wild ocelot, behaves like a devoted dog; the spots come entirely from domestic breeding.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ocicat-on-the-move.jpg?width=1024"},{"name":"Chartreux","rarity":"rare","id":"chartreux","subtitle":"Breed","details":"France's smiling blue monastery cat, a quiet mouser with a woolly double coat and copper-gold eyes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CertosinoFemmina.JPG?width=1024"},{"name":"Korat","rarity":"rare","id":"korat","subtitle":"Breed","details":"Thailand's good-luck cat: silver-tipped blue fur, heart-shaped faces, and luminous green eyes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Korat.jpg?width=1024"},{"name":"Manx","rarity":"rare","id":"manx","subtitle":"Breed","details":"The Isle of Man's tailless wonder, with rabbit-like hind legs and a round, double-coated rump.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Linus%20the%20Manx%201.jpg?width=1024"},{"name":"Japanese Bobtail","rarity":"rare","id":"japanese-bobtail","subtitle":"Breed","details":"Japan's lucky bobtail: a singing, tricolour cat whose pom-pom tail inspired the beckoning cat statues.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Alicia%20the%20Bobtail%20Cat.jpg?width=1024"},{"name":"American Shorthair","rarity":"rare","id":"american-shorthair","subtitle":"Breed","details":"Descended from Mayflower mousers, a sturdy all-American working cat built for barns and laps alike.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/American%20shorthair%20blotched%20tabby.jpg?width=1024"},{"name":"Bombay","rarity":"rare","id":"bombay","subtitle":"Breed","details":"A miniature black panther for the living room: jet fur, copper penny eyes, and a purr like an engine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Bombay%20Cat.jpg?width=1024"},{"name":"Havana Brown","rarity":"rare","id":"havana-brown","subtitle":"Breed","details":"A mahogany-brown charmer with whiskers to match, bred in England and named for a fine cigar's colour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Havana%20Browns%20chocolate%20and%20lilac.jpg?width=1024"},{"name":"Singapura","rarity":"rare","id":"singapura","subtitle":"Breed","details":"One of the smallest breeds, a sepia-ticked Singapore street cat turned treasured, wide-eyed companion.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Curious%20Singapura%202011%20%28cropped%29.jpg?width=1024"},{"name":"Colourpoint","rarity":"rare","id":"colourpoint","subtitle":"Pattern","details":"Cool extremities, dark markings: ears, face, paws, and tail darken where the body runs coldest.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Seal%20point%20Blue%20Eyed%20Cat.jpg?width=1024"},{"name":"White Cat","rarity":"rare","id":"white-cat","subtitle":"Pattern","details":"A masking gene covers every other colour; white cats with blue eyes are often deaf on the blue-eyed side.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2012-02-04%20White%20cat%20in%20the%20snow%20in%20Rome.jpg?width=1024"},{"name":"Orange Tabby","rarity":"rare","id":"orange-tabby","subtitle":"Pattern","details":"The ginger cat: the orange gene rides the X chromosome, so roughly four in five orange tabbies are male.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ginger_kitten_with_an_orange_rubber_rugby.jpg?width=1024"},{"name":"Seal Point","rarity":"rare","id":"seal-point","subtitle":"Pattern","details":"The darkest points, deep seal-brown on ears, mask, paws, and tail, as worn by the classic Siamese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A_classic_seal_point_Siamese_cat.jpg?width=1024"},{"name":"Blue Point","rarity":"rare","id":"blue-point","subtitle":"Pattern","details":"Points in soft slate blue-grey, the cool-toned variation on the Siamese pattern.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/4_month_old_%22traditional%22_Blue_Point_Siamese_cat.JPG?width=1024"},{"name":"Lynx Point","rarity":"rare","id":"lynx-point","subtitle":"Pattern","details":"Points crossed with tabby striping, so the mask and legs carry faint tiger bars.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lynx_point_siamese%2C_Lynx_point_shorthair.jpg?width=1024"},{"name":"Flame Point","rarity":"rare","id":"flame-point","subtitle":"Pattern","details":"Points in warm red-orange, a colourpoint pattern that glows like embers against cream fur.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Flame_Point_Siamese.JPG?width=1024"},{"name":"Cheshire Cat","rarity":"rare","id":"cheshire-cat","subtitle":"Famous Cat","details":"Wonderland's grinning philosopher, who fades away until nothing remains but the smile.","image":"https://upload.wikimedia.org/wikipedia/commons/5/56/Cheshire_Cat_vanishing_%28detail%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Morris the Cat","rarity":"rare","id":"morris-the-cat","subtitle":"Famous Cat","details":"The finicky orange spokescat of 9Lives since 1968, rescued from a shelter and twice run for president in ads.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/Morris_the_Cat_for_President.jpg/1280px-Morris_the_Cat_for_President.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Venus the Two Face Cat","rarity":"rare","id":"venus-the-two-face-cat","subtitle":"Famous Cat","details":"A chimera cat split cleanly down the middle: half black, half orange tabby, with one blue and one green eye.","image":"https://dobrespravy.eu/wp-content/uploads/2021/03/144288752_273399997473857_396856472706676202_o-600x600.jpg"},{"name":"Hamilton the Hipster Cat","rarity":"rare","id":"hamilton-the-hipster-cat","subtitle":"Famous Cat","details":"A rescued Siamese mix whose white markings form a perfect curly moustache under his nose.","image":"https://www.catster.com/wp-content/uploads/2023/11/@hamilton_the_hipster_cat.jpg"},{"name":"Longcat","rarity":"rare","id":"longcat","subtitle":"Famous Cat","details":"Shiro, a Japanese white cat so long when held up that early internet forums declared her legendary.","image":"https://pbs.twimg.com/media/GtuVuenWIAAr-vY.jpg"},{"name":"Henri, le Chat Noir","rarity":"rare","id":"henri-le-chat-noir","subtitle":"Famous Cat","details":"The tuxedo philosopher of YouTube, delivering deadpan French laments about the ennui of the food bowl.","image":"https://static.boredpanda.com/blog/wp-content/uploads/2014/11/famous-internet-cats-9.jpg"},{"name":"Shironeko","rarity":"rare","id":"shironeko","subtitle":"Famous Cat","details":"Japan's zen basket cat, photographed serenely balancing everything from flowers to fruit on his head.","image":"https://i.kym-cdn.com/photos/images/newsfeed/000/263/854/d8a.jpg"},{"name":"Nora the Piano Cat","rarity":"rare","id":"nora-the-piano-cat","subtitle":"Famous Cat","details":"A shelter cat who taught herself to play piano paws-down, and once performed with an orchestra via video.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e4/NoraPianoCat.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Tara the Hero Cat","rarity":"rare","id":"tara-the-hero-cat","subtitle":"Famous Cat","details":"A California tabby who body-slammed a dog attacking her young owner, caught on camera in 2014.","image":"https://alchetron.com/cdn/tara-cat-208de9af-d7bc-40c2-9f29-af9fafcc462-resize-750.jpeg"},{"name":"Scarlett the Hero Cat","rarity":"rare","id":"scarlett-the-hero-cat","subtitle":"Famous Cat","details":"A Brooklyn stray who walked through a burning garage five times to carry out each of her kittens.","image":"https://upload.wikimedia.org/wikipedia/commons/1/16/ScarlettTheCat.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"The First Cat Show","rarity":"rare","id":"the-first-cat-show","subtitle":"History","details":"In 1871, Harrison Weir staged the first organised cat show at London's Crystal Palace, launching the cat fancy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Abyssinian%20Crystal-Palace.jpg?width=1024"},{"name":"The Cyprus Burial","rarity":"rare","id":"the-cyprus-burial","subtitle":"History","details":"A cat buried beside a human in Cyprus some 9,500 years ago is among the earliest evidence of cats living with people.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/African%20Wildcat%20%28Felis%20lybica%29%20%2851659798835%29.jpg?width=1024"},{"name":"Egyptian Cat Mummies","rarity":"rare","id":"egyptian-cat-mummies","subtitle":"History","details":"Ancient Egyptians mummified cats by the million as offerings to Bastet, filling temple cemeteries at Bubastis and beyond.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Egyptian%20-%20Cat%20Mummy%20-%20Walters%20792.jpg?width=500"},{"name":"Dick Whittington's Cat","rarity":"rare","id":"dick-whittingtons-cat","subtitle":"History","details":"London legend credits a poor boy's cat, sold to a rat-plagued king, with founding the fortune that made him Lord Mayor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dick%20Whittington%27s%20Cat%20Sculpture%20on%20the%20Side%20of%20the%20Guildhall.jpg?width=1024"},{"name":"Newton's Cat Flap","rarity":"rare","id":"newtons-cat-flap","subtitle":"History","details":"Cambridge legend says Isaac Newton cut holes in his door for his cat and her kittens, inventing the cat flap.","image":"https://www.petmd.com/sites/default/files/cat-passing-through-catflap-picture-id1070244646.jpg"},{"name":"Hiroshige's Cat in the Window","rarity":"rare","id":"hiroshiges-cat-in-the-window","subtitle":"Art","details":"A white cat gazes over Edo rooftops in Hiroshige's 1857 print, one of ukiyo-e's most beloved cat images.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Asakusa%20tanbo%20torinomachi%20m%C5%8Dde%20LCCN2008660973.jpg?width=1024"},{"name":"Chagall's Cat with a Human Face","rarity":"rare","id":"chagalls-cat-with-a-human-face","subtitle":"Art","details":"In Marc Chagall's Paris Through the Window (1913), a cat with a human face gazes calmly over the city rooftops.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aerrapc%20Guggenheim%20art%20photo%20%2870%29.png?width=500"},{"name":"Foujita's Self-Portrait Cat","rarity":"rare","id":"foujitas-self-portrait-cat","subtitle":"Art","details":"Tsuguharu Foujita painted himself with his cat so often the feline became his signature in 1920s Paris.","image":"https://cdn.sanity.io/images/m2obzhc2/production/270488136ce434bd069f7dcbd5d62098813581cd-1170x1535.jpg/WEB-BLOG-2-0369.jpg?w=1024&q=90&fit=max"},{"name":"Manet's Cat in Olympia","rarity":"rare","id":"manets-cat-in-olympia","subtitle":"Art","details":"At the foot of Olympia's bed stands a small black cat, arched and alert, art history's most analysed pet cameo.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Olympia-manet.jpg?width=1024"},{"name":"Matagot","rarity":"rare","id":"matagot","subtitle":"Mythology","details":"A French spirit cat who, fed first and treated well, brings its master wealth; fed badly, it brings ruin instead.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat_in_front_of_a_door,_Saint-R%C3%A9my-de-Provence_PK-F-EAB.622.jpg?width=1024"},{"name":"The Yule Cat","rarity":"rare","id":"the-yule-cat","subtitle":"Mythology","details":"Iceland's Jolakotturinn prowls the snow at Christmas, eating anyone who finished no work and earned no new clothes.","image":"https://www.katzengesellschaft.com/pictures/Blog/Jolakoetturinn.jpg"},{"name":"King of the Cats","rarity":"rare","id":"king-of-the-cats","subtitle":"Mythology","details":"A British folk tale told across the Isles: a traveller overhears cats mourning their king, and his own cat vanishes to rule.","image":"https://everydayoriginal.com/wp-content/uploads/2024/10/Fowler_king-cat-sm1.jpg"},{"name":"Grimalkin","rarity":"rare","id":"grimalkin","subtitle":"Mythology","details":"The grey cat of old Scots lore, a witch's familiar so famous that Shakespeare gave one to Macbeth's witches.","image":"https://i.pinimg.com/originals/0e/81/2f/0e812fe52edbe0ea05449a1142d34ac3.jpg"},{"name":"Retractable Claws","rarity":"rare","id":"retractable-claws","subtitle":"Anatomy","details":"Claws rest sheathed in the paw and extend only on demand, keeping the weapons sharp for the moment they matter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20claw%20closeup.jpg?width=1024"},{"name":"Third Eyelid","rarity":"rare","id":"third-eyelid","subtitle":"Anatomy","details":"The nictitating membrane sweeps across the eye like a windscreen wiper, cleaning and shielding it as the cat blinks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Third_eyelid.jpg?width=1024"},{"name":"Jacobson's Organ","rarity":"rare","id":"jacobsons-organ","subtitle":"Anatomy","details":"A second scent system in the mouth's roof reads pheromones; the odd open-mouthed flehmen grimace is a cat tasting the air.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat_flehmen_response.jpg?width=1024"},{"name":"Toe Beans","rarity":"rare","id":"toe-beans","subtitle":"Anatomy","details":"Paw pads muffle every step to silence, cushion landings, and carry scent glands that sign the cat's name to the floor.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat_sitting_on_glass_table.jpg?width=1024"},{"name":"Primordial Pouch","rarity":"rare","id":"primordial-pouch","subtitle":"Anatomy","details":"The loose belly flap on even slim cats protects the abdomen in fights and lets the hind legs stretch fully in a sprint.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A_pronounced_primordial_pouch_in_a_male_tabby_mix.jpg?width=1024"},{"name":"Zoomies","rarity":"rare","id":"zoomies","subtitle":"Behavior","details":"The frenetic random activity period: a sudden midnight Grand Prix of hallway sprints and furniture parkour.","image":"https://images.pexels.com/photos/39705288/pexels-photo-39705288.jpeg?auto=compress&cs=tinysrgb&w=1024"},{"name":"Head Bunting","rarity":"rare","id":"head-bunting","subtitle":"Behavior","details":"A forehead pressed firmly into you is a cat depositing friendly scent and declaring you part of the family.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cats%27%20headbutt%3B%20April%202016.jpg?width=1024"},{"name":"If It Fits, I Sits","rarity":"rare","id":"if-it-fits-i-sits","subtitle":"Behavior","details":"Cats choose tight spaces because close walls mean safety and warmth, even when the box is far too small.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20into%20the%20box.jpg?width=1024"},{"name":"The Belly Trap","rarity":"rare","id":"the-belly-trap","subtitle":"Behavior","details":"A rolled-over cat displays its vulnerable belly as a greeting; grabbing it often triggers all four paws at once.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Awwww,%20belly%20rub!!!%20(10156702065).jpg?width=1024"},{"name":"Window Watching","rarity":"rare","id":"window-watching","subtitle":"Behavior","details":"A cat at a window runs a full surveillance shift: birds, neighbours, and weather, all logged in silence.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20Bird%20Watching.jpg?width=800"},{"name":"Hermitage Guard Cats","rarity":"rare","id":"hermitage-guard-cats","subtitle":"Working Cat","details":"Around fifty cats patrol the Hermitage museum's basements, with their own staff, kitchen, and press service.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hermitage%20cat.jpeg?width=1024"},{"name":"Chief Mouser (The Role)","rarity":"rare","id":"chief-mouser-the-role","subtitle":"Working Cat","details":"An official post at the heart of British government since records began in the 1900s, though cats served long before.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Prince%20Giles%20-%20Chief%20Mouser%20of%20Poskenburg.jpg?width=1024"},{"name":"Ship's Cat (The Role)","rarity":"rare","id":"ships-cat-the-role","subtitle":"Working Cat","details":"For centuries every navy and merchant ship carried a cat for rats, luck, and morale; some had their own hammocks.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sailors%20surround%20the%20ship%27s%20cat%20%22Convoy%22%20asleep%20in%20a%20miniature%20hammock%20on%20board%20HMS%20HERMIONE%2C%20Gibraltar%2C%2026%20November%201941.%20A6410.jpg?width=1024"},{"name":"Barn Cat (The Role)","rarity":"rare","id":"barn-cat-the-role","subtitle":"Working Cat","details":"The original working cat: a farm's resident hunter, paid in shelter and food, guarding grain stores for millennia.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black%20barn%20cat%20-%20Public%20Domain%20(2014%20photo;%20cropped%202022).jpg?width=1024"},{"name":"Nitama the Stationmaster","rarity":"rare","id":"nitama-the-stationmaster","subtitle":"Working Cat","details":"Tama's apprentice and successor at Kishi station, promoted from stationmaster trainee to the top job in 2015.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stationmaster%20NITAMA%2020110105.jpg?width=1024"},{"name":"Palmerston the Diplocat","rarity":"rare","id":"palmerston-the-diplocat","subtitle":"Working Cat","details":"Chief mouser of the Foreign Office from 2016, a Battersea rescue who later retired to the countryside.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/London%20October%205%202018%20%2838%29%20Palmerston%20Chief%20Mouser%20of%20the%20Foreign%20%26%20Commonwealth%20Office%20at%20Whitehall%20%2844210185305%29.jpg?width=1024"},{"name":"Gotokuji Temple","rarity":"rare","id":"gotokuji-temple","subtitle":"Cat Place","details":"Tokyo's beckoning-cat temple, where legend says a cat saved a lord from a storm and thousands of maneki-neko gather.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2015-10-20%20Maneki%20neko%20in%20Gotokuji.jpg?width=1024"},{"name":"KattenKabinet","rarity":"rare","id":"kattenkabinet","subtitle":"Cat Place","details":"Amsterdam's cat art museum, founded in memory of a beloved cat, with a few resident cats among the paintings.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat-Cabinet-Amsterdam-Photo%20by%20Pejman%20Akbarzadeh%20Persian%20Dutch%20Network.jpg?width=1024"},{"name":"Torre Argentina Sanctuary","rarity":"rare","id":"torre-argentina-sanctuary","subtitle":"Cat Place","details":"Rome's ancient ruins double as a sanctuary for hundreds of cats, lounging where Caesar fell.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20Sanctuary%2C%20Cats%2C%20Largo%20di%20Torre%20Argentina%2C%20Rome%20-%20398%20%2819257774921%29.jpg?width=1024"},{"name":"The Poezenboot","rarity":"rare","id":"the-poezenboot","subtitle":"Cat Place","details":"Amsterdam's floating cat sanctuary, a houseboat of rescued cats riding at anchor since 1966.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Poezenboot%20Amsterdam%201.jpg?width=1024"},{"name":"Lanai Cat Sanctuary","rarity":"rare","id":"lanai-cat-sanctuary","subtitle":"Cat Place","details":"A Hawaiian open-air sanctuary home to hundreds of rescued cats, sometimes called the Fur Seasons by visitors.","image":"https://lanaicatsanctuary.org/wp-content/uploads/2019/06/Hawaii-Cats-Play.jpg"},{"name":"Snowshoe","rarity":"uncommon","id":"snowshoe","subtitle":"Breed","details":"A Siamese in white boots: pointed markings, blue eyes, and four permanently dipped-in-snow paws.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chizhik%20Cat.jpg?width=1024"},{"name":"Balinese","rarity":"uncommon","id":"balinese","subtitle":"Breed","details":"Essentially a long-haired Siamese: silky, elegant, chatty, and named for graceful Balinese dancers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Balinese-cat.jpg?width=1024"},{"name":"Oriental Shorthair","rarity":"uncommon","id":"oriental-shorthair","subtitle":"Breed","details":"A Siamese in every colour of the rainbow, with green eyes and bat-wing ears; over 300 colour combinations exist.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oriental%20Shorthair%20cat.jpg?width=1024"},{"name":"Turkish Van","rarity":"uncommon","id":"turkish-van","subtitle":"Breed","details":"The swimming cat of Lake Van, mostly white with colour only on head and tail, and famously fond of water.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Morris%2C%20a%20cat%20of%20the%20Turkish%20Van.jpg?width=1024"},{"name":"American Curl","rarity":"uncommon","id":"american-curl","subtitle":"Breed","details":"A Californian stray's ears curled backwards into perfect scrolls; kittens are born straight-eared, then curl.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/ACL%20Americal%20curl%20%284194130509%29.jpg?width=1024"},{"name":"Munchkin","rarity":"uncommon","id":"munchkin","subtitle":"Breed","details":"The short-legged charmer: a natural mutation gives it dachshund-like legs and a ferret's playful energy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Munchkin%20cat%202.jpg?width=1024"},{"name":"Savannah","rarity":"uncommon","id":"savannah","subtitle":"Breed","details":"A domestic cat crossed with an African serval: tall, spotted, and among the largest of all pet cats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Savannah-F3-Kater.jpg?width=1024"},{"name":"Lykoi","rarity":"uncommon","id":"lykoi","subtitle":"Breed","details":"The werewolf cat: a patchy, half-haired coat and masked face give this Tennessee breed its wolfish look.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/8-month-old%20male%20Lykoi.jpg?width=1024"},{"name":"Khao Manee","rarity":"uncommon","id":"khao-manee","subtitle":"Breed","details":"Thailand's white gem cat, treasured for jewel eyes that may be blue, gold, or one of each.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Khao%20Manee%202%20%22Gally%22.jpg?width=1024"},{"name":"Nebelung","rarity":"uncommon","id":"nebelung","subtitle":"Breed","details":"A long-haired, mist-blue cat whose name means creature of the mist in German; shy, soft, and devoted.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20Nebelung%20cat%20chilling%20on%20a%20bedroom%20counter.jpg?width=1024"},{"name":"Somali","rarity":"uncommon","id":"somali","subtitle":"Breed","details":"The fox cat: a long-haired Abyssinian with a bushy tail, ticked fur, and endless mischievous energy.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Somali%20cat%20in%20Fif%C3%A9%20Worldshow%20.jpg?width=1024"},{"name":"Australian Mist","rarity":"uncommon","id":"australian-mist","subtitle":"Breed","details":"Australia's own breed, wrapped in a soft mist of spots and marbling over a gentle, home-loving nature.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black%20tortoiseshell%20silver%20tabby%20cat.jpg?width=1024"},{"name":"Burmilla","rarity":"uncommon","id":"burmilla","subtitle":"Breed","details":"A happy accident between a Burmese and a Chinchilla Persian: silver-shaded, eyeliner-eyed, and easygoing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Burmilla.JPG?width=1024"},{"name":"Peterbald","rarity":"uncommon","id":"peterbald","subtitle":"Breed","details":"A Russian hairless breed from St. Petersburg; some are born bald, others wear a coat like peach velvet.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20sfinks.jpg?width=1024"},{"name":"Donskoy","rarity":"uncommon","id":"donskoy","subtitle":"Breed","details":"A hairless Russian breed whose baldness comes from a dominant gene, unrelated to the Canadian Sphynx.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20don%20sphinx.JPG?width=1024"},{"name":"American Bobtail","rarity":"uncommon","id":"american-bobtail","subtitle":"Breed","details":"A rugged American breed with a short, expressive tail, tufted ears, and a natural hunter's gaze.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/American%20bobtail%202.jpg?width=500"},{"name":"American Wirehair","rarity":"uncommon","id":"american-wirehair","subtitle":"Breed","details":"Every hair of its coat is crimped like steel wool; the breed began with one wiry kitten in New York in 1966.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/American%20Wirehair%20cat%20tired.jpg?width=1024"},{"name":"Cymric","rarity":"uncommon","id":"cymric","subtitle":"Breed","details":"The long-haired Manx: tailless, round, and double-coated, named for Wales, the Manx cat's Celtic cousinland.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/CymricCatPerched.jpg?width=1024"},{"name":"Chausie","rarity":"uncommon","id":"chausie","subtitle":"Breed","details":"A domestic breed developed from jungle cat crosses: tall, cougar-toned, and intensely loyal to its family.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chausie%20IMG%205217%20%28cropped%29.jpg?width=1024"},{"name":"Serengeti","rarity":"uncommon","id":"serengeti","subtitle":"Breed","details":"Bred to evoke a serval using only domestic cats: long legs, huge ears, and bold dark spots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Serengetimalecat.jpg?width=1024"},{"name":"Elf Cat","rarity":"uncommon","id":"elf-cat","subtitle":"Breed","details":"A hairless cat with curled-back ears, blending Sphynx skin with American Curl scrolls.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Elf1111111.jpg?width=1024"},{"name":"Highlander","rarity":"uncommon","id":"highlander","subtitle":"Breed","details":"A big, curled-eared American breed with bobbed tails and a dog-like love of games and people.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Highlander%20cat%20%282010%29%20Hugo%20by%20TAnthony.jpg?width=1024"},{"name":"Domestic Shorthair","rarity":"uncommon","id":"domestic-shorthair","subtitle":"Breed","details":"The classic moggy: no pedigree, every colour, and the most common beloved cat on Earth.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20Iran.jpg?width=1024"},{"name":"Toyger","rarity":"uncommon","id":"toyger","subtitle":"Breed","details":"A domestic cat bred to look like a tiny tiger, with vertical orange stripes and a glittered coat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Olaf%20Toyger%20Bellille.jpg?width=1024"},{"name":"Bicolour","rarity":"uncommon","id":"bicolour","subtitle":"Pattern","details":"White plus one colour in any balance, from a single chest splash to the near-total white of the Van.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bicolor_he-cat.JPG?width=1024"},{"name":"Van Pattern","rarity":"uncommon","id":"van-pattern","subtitle":"Pattern","details":"Colour confined to the head and tail on an otherwise white cat, named for the Turkish Van breed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Van_kedisi_-_DSC00918.jpg?width=1024"},{"name":"Smoke","rarity":"uncommon","id":"smoke","subtitle":"Pattern","details":"Each hair is pale at the root and dark at the tip, so the coat seems to smoulder as the cat moves.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Genova-Gatto_Ettore_gennaio_2006.jpg?width=1024"},{"name":"Chinchilla","rarity":"uncommon","id":"chinchilla","subtitle":"Pattern","details":"Only the very tip of each hair is coloured, dusting a white undercoat with silver or gold light.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Persian_cat_chinchilla_golden_male_and_silver_female.jpg?width=1024"},{"name":"Torbie","rarity":"uncommon","id":"torbie","subtitle":"Pattern","details":"A tortoiseshell wearing tabby stripes: patched colour and pattern in one complicated, glorious coat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Xena%2C%20female%20%22torbie%22.jpg?width=1024"},{"name":"Odd Eyes","rarity":"uncommon","id":"odd-eyes","subtitle":"Pattern","details":"Heterochromia: one blue eye and one gold or green, most often seen lighting up a white coat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/June_odd-eyed-cat.jpg?width=1024"},{"name":"Mitted","rarity":"uncommon","id":"mitted","subtitle":"Pattern","details":"Four white gloves on the paws, the signature finish of Birmans and Snowshoe cats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cuccioli-2006-15.jpg?width=1024"},{"name":"Rosettes","rarity":"uncommon","id":"rosettes","subtitle":"Pattern","details":"Hollow, doughnut-shaped spots edged in dark pigment, the prized marking of the Bengal breed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bengal_cat%2C_five_months_old_%282474931892%29.jpg?width=1024"},{"name":"Marbled Coat","rarity":"uncommon","id":"marbled-coat","subtitle":"Pattern","details":"A classic tabby stretched and swirled into chaotic marble, dramatic in Bengals and Australian Mists.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Snow_Marble_Bengal_Cat_Male_18_Months_standing.jpg?width=1024"},{"name":"Green Eyes","rarity":"uncommon","id":"green-eyes","subtitle":"Pattern","details":"The commonest feline eye colour worldwide, from pale gooseberry to deep emerald.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Green_cat_eyes_in_macro_%28Unsplash%29_%28cropped%29.jpg?width=1024"},{"name":"Blue Eyes","rarity":"uncommon","id":"blue-eyes","subtitle":"Pattern","details":"No pigment, just light scattering in the iris; all kittens are born with blue eyes before they change.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BLUE_CAT_EYE_CLOSE_UP.jpg?width=1024"},{"name":"Amber Eyes","rarity":"uncommon","id":"amber-eyes","subtitle":"Pattern","details":"Eyes of liquid copper and gold, common in Burmese and British Shorthairs, glowing against dark coats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chat_gris_et_blanc_aux_yeux_cuivr%C3%A9s_dans_les_herbes_hautes.jpg?width=1024"},{"name":"Agouti","rarity":"uncommon","id":"agouti","subtitle":"Pattern","details":"The banded hair itself: alternating light and dark zones along each shaft, the engine of ticked coats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Abyssinian_cat_-_Patricia.jpg?width=1024"},{"name":"Creme Puff","rarity":"uncommon","id":"creme-puff","subtitle":"Famous Cat","details":"The oldest cat ever recorded, an Austin tabby mix who lived to 38 years and 3 days.","image":"https://feedmehooman.com/media/news/creme-puff-oldest-cat-ever-38-years-og.jpg"},{"name":"Blackie the Richest Cat","rarity":"uncommon","id":"blackie-the-richest-cat","subtitle":"Famous Cat","details":"A British cat left some seven million pounds by his owner in 1988, long listed as the world's richest cat.","image":"https://pub-1a95c923aec7478dba6f67a00666f3b8.r2.dev/2025/04/Blackie-the-cat-GUINNES-WORLD-RECORDS-Instagram-1024x759.jpeg"},{"name":"Didga","rarity":"uncommon","id":"didga","subtitle":"Famous Cat","details":"An Australian rescue cat who rides skateboards, surfboards, and shoulder perches like a seasoned pro.","image":"https://www.guinnessworldrecords.com/news/2019/2/images/didga-skateboard-561248.jpg"},{"name":"Atchoum","rarity":"uncommon","id":"atchoum","subtitle":"Famous Cat","details":"A Persian with hypertrichosis, a hormone quirk that gives him a wild werewolf mane and mad-scientist whiskers.","image":"https://cdn-images-1.medium.com/max/1600/1*LB65a62Tpm3rEjJvVEZjDg.jpeg"},{"name":"Monty the Cat","rarity":"uncommon","id":"monty-the-cat","subtitle":"Famous Cat","details":"A Danish rescue born without a nasal bridge, whose gentle down-turned face champions special-needs adoption.","image":"https://static.boredpanda.com/blog/wp-content/uploads/2014/11/cute-cat-without-nosal-bone-monty-4.jpg"},{"name":"Sam the Eyebrow Cat","rarity":"uncommon","id":"sam-the-eyebrow-cat","subtitle":"Famous Cat","details":"A white cat whose two black brow markings keep him looking permanently, adorably concerned.","image":"https://www.fourpaws.com/-/media/Project/OneWeb/FourPaws/Images/articles/quizzes-and-activities/10-funny-instagram-pet-accounts/samhaseyebrows.jpg"},{"name":"Smudge the Table Cat","rarity":"uncommon","id":"smudge-the-table-cat","subtitle":"Famous Cat","details":"The unimpressed white cat of the woman-yelling-at-a-cat meme, photographed mid-protest at a salad.","image":"https://assets.dev-filo.dift.io/img/2019/09/03/smudge_lord_sq.jpg"},{"name":"Pop Cat","rarity":"uncommon","id":"pop-cat","subtitle":"Famous Cat","details":"A white cat whose mouth pops open with a click, remixed into one of the internet's simplest, perfect memes.","image":"https://i.pinimg.com/originals/cc/cc/4e/cccc4ea060c18e4b96d3b5cab9e52e51.png"},{"name":"Maxwell the Cat","rarity":"uncommon","id":"maxwell-the-cat","subtitle":"Famous Cat","details":"Dingus the black-and-white cat, spun slowly into meme fame as Maxwell in a beloved sandbox game mod.","image":"https://images-cdn.9gag.com/photo/aVvyn8v_700b.jpg"},{"name":"Bongo Cat","rarity":"uncommon","id":"bongo-cat","subtitle":"Famous Cat","details":"A chubby cartoon cat endlessly drumming on bongos, keyboards, and anything else a song requires.","image":"https://ih1.redbubble.net/image.2415266922.3146/pp,504x498-pad,600x600,f8f8f8.jpg"},{"name":"Chessie","rarity":"uncommon","id":"chessie","subtitle":"Famous Cat","details":"The Chesapeake and Ohio Railway's sleeping kitten, drawn in 1933 and ridden into history as a beloved mascot.","image":"https://upload.wikimedia.org/wikipedia/commons/2/22/Required_Together_Again%21%28Chessie%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Bagpuss","rarity":"uncommon","id":"bagpuss","subtitle":"Famous Cat","details":"A saggy old cloth cat from British television, whose yawns woke a shop of magical repairing mice.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Bagpuss_in_Canterbury.jpg/1280px-Bagpuss_in_Canterbury.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Figaro","rarity":"uncommon","id":"figaro","subtitle":"Famous Cat","details":"Pinocchio's tuxedo kitten, so charming that Walt Disney gave him his own cartoon shorts with Minnie Mouse.","image":"https://i.pinimg.com/474x/4a/ff/b6/4affb65196086c8301eed4f8edb4c3e1.jpg"},{"name":"Duchess","rarity":"uncommon","id":"duchess","subtitle":"Famous Cat","details":"The elegant white Persian mother of The Aristocats, raising three musical kittens in Parisian high society.","image":"https://www.cuteness.com/img/gallery/16-very-impurrtant-disney-cats-that-you-should-know-about-upgrade/duchess-from-the-aristocats-1731523261.jpg"},{"name":"Pangur Ban","rarity":"uncommon","id":"pangur-ban","subtitle":"History","details":"A 9th-century Irish monk wrote a poem to his white cat Pangur, each of them hunting happily: he words, the cat mice.","image":"https://substack-post-media.s3.amazonaws.com/public/images/09a02a8e-cc15-43f2-aa9e-b7fd0ca07d1e_663x900.jpeg"},{"name":"Viking Ship Cats","rarity":"uncommon","id":"viking-ship-cats","subtitle":"History","details":"Norse sailors kept cats aboard for rodent control and luck; the Norwegian Forest Cat descends from that seafaring stock.","image":"https://catway.net/wp-content/uploads/2025/02/Norwegian-Forest-Cat-21.jpeg"},{"name":"Gayer-Anderson Cat","rarity":"uncommon","id":"gayer-anderson-cat","subtitle":"History","details":"A bronze Egyptian cat statue from around 600 BC, wearing gold jewellery, now among the British Museum's treasures.","image":"https://cdn.thecollector.com/wp-content/uploads/2021/11/gayer-anderson-cat.jpg?width=678&quality=100&dpr=2"},{"name":"Hemingway's Six-Toed Cats","rarity":"uncommon","id":"hemingways-six-toed-cats","subtitle":"History","details":"A sea captain gave Ernest Hemingway a polydactyl cat; dozens of her many-toed descendants still roam his Key West home.","image":"https://image.yachtcharterfleet.com/w1040/h545/qh/cs0-574-5616-2933/k21092fa2/cms/photo/1832652/hemingway-cats.jpg"},{"name":"Tommaso the Millionaire Cat","rarity":"uncommon","id":"tommaso-the-millionaire-cat","subtitle":"History","details":"A Roman former stray who inherited some ten million euros of property from his owner in 2011.","image":"https://img-s1.onedio.com/id-64ea103a3444aa3312e63f63/rev-0/w-600/h-466/f-jpg/s-07d62143b9128e96511d4497d85e1bb62615e113.jpg"},{"name":"The Plague Cat Legend","rarity":"uncommon","id":"the-plague-cat-legend","subtitle":"History","details":"A popular tale blames medieval cat-killing for worsening the Black Death; historians note the story is mostly legend, not record.","image":"https://pbs.twimg.com/media/D5ucu1HXsAAQ7XR?format=jpg&name=medium"},{"name":"Cats of the Mayflower","rarity":"uncommon","id":"cats-of-the-mayflower","subtitle":"History","details":"Pilgrim ships carried cats as working mousers; their descendants became the American Shorthair breed.","image":"https://www.pictorem.com/uploads/collection/C/CG4IIQ5QNM/600_Panoramic-Images_183511.jpg"},{"name":"Renoir's Girl with a Cat","rarity":"uncommon","id":"renoirs-girl-with-a-cat","subtitle":"Art","details":"Renoir's portrait of young Julie Manet cradling a calm tabby, painted in soft summer light in 1887.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pierre-Auguste%20Renoir%20-%20Julie%20Manet.jpg?width=500"},{"name":"Steinlen's Winter Cat","rarity":"uncommon","id":"steinlens-winter-cat","subtitle":"Art","details":"Steinlen's street cats of Montmartre, drawn from the strays he fed daily on his walks through Paris.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/1884%20-%20Steinlen%20-%20Cat%20and%20Mice.JPG?width=1024"},{"name":"The White Cat by Bonnard","rarity":"uncommon","id":"the-white-cat-by-bonnard","subtitle":"Art","details":"Pierre Bonnard's white cat, stretched into a comical arc, is a small masterpiece of observed feline anatomy.","image":"https://i.etsystatic.com/41775420/r/il/a41797/7023805395/il_600x600.7023805395_fyru.jpg"},{"name":"Balthus and Mitsou","rarity":"uncommon","id":"balthus-and-mitsou","subtitle":"Art","details":"At eleven, Balthus published a book of drawings about Mitsou, the stray cat he rescued, with a preface by Rilke.","image":"http://wordlessnovels.com/wp-content/uploads/2026/04/ink-drawing-by-Balthus-for-plate-23-of-Mitsou.jpg"},{"name":"Cath Palug","rarity":"uncommon","id":"cath-palug","subtitle":"Mythology","details":"Welsh legend's monstrous cat, raised on Anglesey, who slew nine score warriors before falling to Cei's shield.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/BnF-fr10420-fol040v-historiated-A-chat-losane-detail.jpg?width=1024"},{"name":"Mafdet","rarity":"uncommon","id":"mafdet","subtitle":"Mythology","details":"Among Egypt's earliest deities, a cat goddess of justice who struck down snakes and scorpions with her claws.","image":"https://symbolsage.com/wp-content/uploads/2022/05/Egyptian-Goddess-Mafdet.png"},{"name":"Sekhmet","rarity":"uncommon","id":"sekhmet","subtitle":"Mythology","details":"Egypt's lioness goddess of war and healing, Bastet's fierce counterpart: the same divine fire, ungentled.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Granite%20Statue%20of%20Sitting%20Lioness%20Goddess%20Sekhmet%2C%20from%20Temple%20of%20Mut%20at%20Karnak%2C%20Dynasty%2018%2C%20c.%201391-1353%20BC%20%2848465036896%29.jpg?width=1024"},{"name":"Kasha","rarity":"uncommon","id":"kasha","subtitle":"Mythology","details":"Japan's corpse-stealing cat spirit, whose fiery cart descends during storms to snatch the dead from funerals.","image":"https://fanfun.jp/wp-content/uploads/2023/05/63b6302973b6ba23a36ab14668f42bfa-768x484.jpg"},{"name":"Floating Collarbones","rarity":"uncommon","id":"floating-collarbones","subtitle":"Anatomy","details":"A cat's clavicles float free in muscle instead of anchoring to bone, so any gap the head fits through, the body follows.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20Flap.jpg?width=1024"},{"name":"Flexible Spine","rarity":"uncommon","id":"flexible-spine","subtitle":"Anatomy","details":"Loosely coupled vertebrae let a cat rotate its front and back halves in opposite directions, mid-air or mid-nap.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Stretching_cat.jpg?width=1024"},{"name":"Ear Muscles","rarity":"uncommon","id":"ear-muscles","subtitle":"Anatomy","details":"Some 32 muscles steer each ear independently through 180 degrees, swivelling satellite dishes for faint rustles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Savannah_Cat_closeup.jpg?width=1024"},{"name":"Nose Print","rarity":"uncommon","id":"nose-print","subtitle":"Anatomy","details":"The ridges and bumps on a cat's nose leather form a pattern as unique as a human fingerprint.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat_nose_close-up.jpg?width=1024"},{"name":"Carnassial Teeth","rarity":"uncommon","id":"carnassial-teeth","subtitle":"Anatomy","details":"A cat's back teeth work like scissors, shearing meat and tendon; cats have no flat molars for grinding at all.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Teeth%20of%20a%20cat%202010-05-05.jpg?width=1024"},{"name":"Righting Reflex","rarity":"uncommon","id":"righting-reflex","subtitle":"Anatomy","details":"Using spine and inner ear, a falling cat twists upright in fractions of a second and lands prepared on all fours.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Falling_cat_1894.jpg?width=1024"},{"name":"Polydactyl Paws","rarity":"uncommon","id":"polydactyl-paws","subtitle":"Anatomy","details":"Extra toes are a harmless mutation once favoured by sailors; record holders sport nearly thirty toes in total.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Feline_polydactylism.jpg?width=1024"},{"name":"Eyebrow Whiskers","rarity":"uncommon","id":"eyebrow-whiskers","subtitle":"Anatomy","details":"Long vibrissae sprout above each eye in neat rows, warning a cat of anything approaching its face from above.","image":"https://images.pexels.com/photos/33676335/pexels-photo-33676335.jpeg?auto=compress&cs=tinysrgb&w=1024"},{"name":"Scent Glands","rarity":"uncommon","id":"scent-glands","subtitle":"Anatomy","details":"Glands in the cheeks, chin, temples, and tail base lay down friendly scent signatures with every head-bump and rub.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Meow.love.jpg?width=1024"},{"name":"Sweaty Paws","rarity":"uncommon","id":"sweaty-paws","subtitle":"Anatomy","details":"Cats sweat almost exclusively through their paw pads, leaving damp little footprints on hot or anxious days.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Magnolia%20Street%2C%20Uptown%20New%20Orleans%2C%203400%20block%2016%20May%202023%20-%20Sidewalk%20cat%20paw%20prints.jpg?width=1024"},{"name":"Kitten Milk Teeth","rarity":"uncommon","id":"kitten-milk-teeth","subtitle":"Anatomy","details":"Kittens grow 26 baby teeth, replaced by 30 adult teeth by about six months, in a week of extra chewing.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat_crying.jpg?width=1024"},{"name":"Meowing at Humans","rarity":"uncommon","id":"meowing-at-humans","subtitle":"Behavior","details":"Adult cats rarely meow at each other; the meow is a language kept almost exclusively for talking to people.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Meow%20cat%20-%20Mdebona.jpg?width=1024"},{"name":"Bringing Gifts","rarity":"uncommon","id":"bringing-gifts","subtitle":"Behavior","details":"A presented mouse on the doorstep is provision-sharing behaviour: you are family, and family gets fed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20running%20with%20mouse%20in%20mouth.jpg?width=1024"},{"name":"Sitting in the Sink","rarity":"uncommon","id":"sitting-in-the-sink","subtitle":"Behavior","details":"A cool porcelain sink fits a curled cat exactly, which is why so many cats claim the bathroom basin as a second bed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20in%20Sink.jpg?width=1024"},{"name":"Sitting on Laptops","rarity":"uncommon","id":"sitting-on-laptops","subtitle":"Behavior","details":"Warm, centre of your attention, and smelling of you: from a cat's view, your laptop is the finest seat in the house.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Midge%20cat%20and%20computer.jpg?width=1024"},{"name":"Following You to the Bathroom","rarity":"uncommon","id":"following-you-to-the-bathroom","subtitle":"Behavior","details":"Closed doors offend feline territorial logic; a bathroom visit without an escort is simply not permitted.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bilal%20Sink%20-%20small%20cat%20in%20sink%20of%20home%20bathroom%2C%20New%20Orleans%2C%201999.jpg?width=1024"},{"name":"Tail Language","rarity":"uncommon","id":"tail-language","subtitle":"Behavior","details":"Tail high means friendly, puffed means startled, and a slow sweep means a decision is being made about you.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20tail.jpg?width=1024"},{"name":"Airplane Ears","rarity":"uncommon","id":"airplane-ears","subtitle":"Behavior","details":"Ears flattened sideways signal irritation or overwhelm, a clear early warning in feline body language.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hannibal%20Poenaru%20-%20Nasty%20cat%20%21%20%28by-sa%29.jpg?width=1024"},{"name":"The Hunting Crouch","rarity":"uncommon","id":"the-hunting-crouch","subtitle":"Behavior","details":"Low, still, eyes locked: the crouch gathers a cat's whole body into a spring aimed at one exact point.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Crouching%20Cat,%20Hidden%20Lizard.jpg?width=1024"},{"name":"Bunny Kicking","rarity":"uncommon","id":"bunny-kicking","subtitle":"Behavior","details":"Grasping with the front paws while the back legs rake is serious hunting machinery, best deployed on toy kickers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eponine%20my%20cat.jpg?width=1024"},{"name":"Halloween Cat Pose","rarity":"uncommon","id":"halloween-cat-pose","subtitle":"Behavior","details":"Back arched, fur fluffed, body sideways: a startled cat making itself as large as theatre and physics allow.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arched%20Cyprus%20and%20Tabby.jpg?width=1024"},{"name":"Sleeping Sixteen Hours","rarity":"uncommon","id":"sleeping-sixteen-hours","subtitle":"Behavior","details":"Cats sleep 12 to 16 hours a day in rotating naps, an energy budget built for short, explosive hunts.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Boo-Boo%20Kitty%20%285393938284%29.jpg?width=1024"},{"name":"Crepuscular Hours","rarity":"uncommon","id":"crepuscular-hours","subtitle":"Behavior","details":"Cats are wired for dawn and dusk, when prey stirs; the 5 a.m. wake-up call is ancient programming, not malice.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20at%20dawn%20%2827672596216%29.jpg?width=1024"},{"name":"Gladstone the Treasury Cat","rarity":"uncommon","id":"gladstone-the-treasury-cat","subtitle":"Working Cat","details":"Named for a four-time prime minister, this black cat took up mousing duties at HM Treasury in 2016.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gladstone%20in%20%22Cat%20in%20the%20Hat%22%20costume.jpg?width=1024"},{"name":"Humphrey the Downing Cat","rarity":"uncommon","id":"humphrey-the-downing-cat","subtitle":"Working Cat","details":"A stray who wandered into Downing Street in 1989 and served three prime ministers as chief mouser.","image":"https://upload.wikimedia.org/wikipedia/en/4/48/Humphrey_mouser.jpg"},{"name":"Casper the Commuter Cat","rarity":"uncommon","id":"casper-the-commuter-cat","subtitle":"Working Cat","details":"A Plymouth cat who rode the number 3 bus so regularly that drivers knew his stop and the company made him a pass.","image":"https://upload.wikimedia.org/wikipedia/en/e/e1/Casper_the_cat,_sitting_in_bus.jpg"},{"name":"George the Station Cat","rarity":"uncommon","id":"george-the-station-cat","subtitle":"Working Cat","details":"The ginger station cat of Stourbridge Junction in England, a commuter favourite with fans around the world.","image":"assets/sets/cats/images/george-the-station-cat.jpg"},{"name":"Stubbs, Mayor of Talkeetna","rarity":"uncommon","id":"stubbs-mayor-of-talkeetna","subtitle":"Working Cat","details":"A part-Manx yellow tabby elected honorary mayor of Talkeetna, Alaska in 1997, holding the office for twenty years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mayor%20Stubbs.jpg?width=1024"},{"name":"Library Cat (The Role)","rarity":"uncommon","id":"library-cat-the-role","subtitle":"Working Cat","details":"Libraries worldwide keep cats for pest control and patron delight; an official society once mapped hundreds of them.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20of%20the%20Gulbenkian%20Library%2C%20Armenian%20Quarters%2C%20Jerusalem%20Old%20Town%2C%20Israel%202012%20%28cropped%29.JPG?width=1024"},{"name":"Bookshop Cats","rarity":"uncommon","id":"bookshop-cats","subtitle":"Working Cat","details":"Independent bookshops keep resident cats who shelve themselves among the stock and supervise from the counter.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20Second%20Cat%20Snoozes.jpg?width=1024"},{"name":"Theatre Cats","rarity":"uncommon","id":"theatre-cats","subtitle":"Working Cat","details":"London theatres keep cats backstage, where they are treated as cast members and sometimes appear in programmes.","image":"https://www.purr-n-fur.org.uk/featuring/work/theatre/wk-ent01a-globeold-beerbohm01.jpg"},{"name":"Hotel Cats","rarity":"uncommon","id":"hotel-cats","subtitle":"Working Cat","details":"Grand hotels keep resident cats as greeters; New York's Algonquin has hosted a famous line of them since the 1930s.","image":"https://www.lovemeow.com/media-library/image.jpg?id=10181324&width=980"},{"name":"Distillery Cats","rarity":"uncommon","id":"distillery-cats","subtitle":"Working Cat","details":"Whisky distilleries keep cats to guard the barley, a tradition so deep that several have statues and whiskies named for cats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Maude%20and%20the%20Fermenter.jpg?width=1024"},{"name":"Brewery Cats","rarity":"uncommon","id":"brewery-cats","subtitle":"Working Cat","details":"Brewers keep cats for the same ancient reason as distillers: grain draws mice, and mice draw cats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2010%20%2C%20The%20brewery%20cat%2C%20Springs%20Brewery%20-%20geograph.org.uk%20-%201892797.jpg?width=1024"},{"name":"Therapy Cats","rarity":"uncommon","id":"therapy-cats","subtitle":"Working Cat","details":"Registered therapy cats visit hospitals, schools, and care homes, lowering stress one lap at a time.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Unitarian%20Church%20Cat%20Therapy%204.JPG?width=1024"},{"name":"Bubba the School Cat","rarity":"uncommon","id":"bubba-the-school-cat","subtitle":"Working Cat","details":"A California school cat who patrolled the grounds for years and appeared in the yearbook like any other student.","image":"https://shareably.net/wp-content/uploads/2017/09/12363007_1684104998512510_2987470515902105881_o.jpg"},{"name":"Flame the Fire Station Cat","rarity":"uncommon","id":"flame-the-fire-station-cat","subtitle":"Working Cat","details":"A South Carolina fire station's resident cat, adopted after wandering in and promoted to morale officer.","image":"https://www.lovemeow.com/media-library/image.jpg?id=9960998&width=980"},{"name":"Kuching, Cat City","rarity":"uncommon","id":"kuching-cat-city","subtitle":"Cat Place","details":"The Malaysian city whose name echoes the word for cat, complete with a cat museum and cat statues.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20Monument%20Kuching.jpg?width=1024"},{"name":"Ainoshima Cat Island","rarity":"uncommon","id":"ainoshima-cat-island","subtitle":"Cat Place","details":"A small Fukuoka island whose friendly ferry-port cats became a pilgrimage site for cat photographers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20in%20Ainoshima%2003.jpg?width=1024"},{"name":"Enoshima Cats","rarity":"uncommon","id":"enoshima-cats","subtitle":"Cat Place","details":"The shrine island near Tokyo where cats lounge on the steps, unbothered by the crowds climbing past.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20at%20Enoshima%202005.jpg?width=1024"},{"name":"St. Nicholas of the Cats","rarity":"uncommon","id":"st-nicholas-of-the-cats","subtitle":"Cat Place","details":"A Cyprus monastery said to keep cats since the 4th century, when they were imported to hunt venomous snakes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Akrotiri%2001-2017%20img03%20StNicholas%20of%20the%20Cats.jpg?width=1024"},{"name":"Syros Cats","rarity":"uncommon","id":"syros-cats","subtitle":"Cat Place","details":"The Greek island of Syros runs a celebrated rescue programme, with feeding stations across its marble capital.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/20221028%20451%20Syros%2006.jpg?width=1024"},{"name":"Kotor's Cats","rarity":"uncommon","id":"kotors-cats","subtitle":"Cat Place","details":"Montenegro's walled old town belongs to its cats, who have a museum, a square, and official local affection.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Street%20cat%20in%20Kotor%2C%20Montenegro.jpg?width=500"},{"name":"The First Cat Cafe","rarity":"uncommon","id":"the-first-cat-cafe","subtitle":"Cat Place","details":"Cat cafes began in Taipei in 1998 and flowered in Japan, pairing coffee with adoptable, unbothered cats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tabby%20Cat%20at%20a%20Cat%20Cafe%20%28Taipei%29.jpg?width=1024"},{"name":"Republic of Cats","rarity":"uncommon","id":"republic-of-cats","subtitle":"Cat Place","details":"A St. Petersburg cat museum and cafe where resident cats, many formerly of the Hermitage, receive visitors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%27s%20republic%2C%20Saint%20Petersburg%20%2811327784854%29.jpg?width=1024"},{"name":"Kattenstoet Cat Parade","rarity":"uncommon","id":"kattenstoet-cat-parade","subtitle":"Cat Place","details":"Ypres, Belgium throws a triennial cat festival with floats, costumes, and a parade honouring its medieval cats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ieper%20Duivel%20Pietje%20Pek.JPG?width=1024"},{"name":"Okishima Cat Island","rarity":"uncommon","id":"okishima-cat-island","subtitle":"Cat Place","details":"The only inhabited island in Japan's largest lake, where cats wander a village with no cars at all.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oki%20island%20port%2C%20Lake%20Biwa%202017-08-14.jpg?width=1024"},{"name":"RagaMuffin","rarity":"common","id":"ragamuffin","subtitle":"Breed","details":"A big, cuddly Californian breed with a rabbit-soft coat, bred to be held like a baby and love it.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ragamuffin.jpg?width=1024"},{"name":"Selkirk Rex","rarity":"common","id":"selkirk-rex","subtitle":"Breed","details":"The cat in sheep's clothing: a Montana shelter kitten's curly coat founded a breed of plush teddy bears.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SRL%20%28Selkirk%20Rex%20semi-longhair%29%20%284171118303%29.jpg?width=1024"},{"name":"LaPerm","rarity":"common","id":"laperm","subtitle":"Breed","details":"An Oregon barn cat born bald grew a coat of loose curls; the breed's name nods to its permanent wave.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Kururu-LaPermCat%20in%20Cat%20Cafe.jpg?width=1024"},{"name":"Pixie-bob","rarity":"common","id":"pixie-bob","subtitle":"Breed","details":"A Pacific Northwest breed built to resemble a bobcat: bobbed tail, spotted coat, and polydactyl paws.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/AnsonRoadLynxJenkinsPowerfulPixieBobMale.JPG?width=1024"},{"name":"Kurilian Bobtail","rarity":"common","id":"kurilian-bobtail","subtitle":"Breed","details":"A rugged island cat from the Kuril chain, with a pom-pom tail unique to every individual, like a fingerprint.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/KBL-%20Kurilian%20bobtail%20%283153184885%29.jpg?width=1024"},{"name":"Mekong Bobtail","rarity":"common","id":"mekong-bobtail","subtitle":"Breed","details":"A pointed Thai breed with a short, kinked tail, descended from cats kept in Siamese royal palaces.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mekong%20bobtail.jpg?width=1024"},{"name":"Aegean","rarity":"common","id":"aegean","subtitle":"Breed","details":"Greece's natural island cat, at home fishing around Aegean harbours in a white-and-colour coat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Aegean%20cat%20Marilyn%2030-1-2021.jpg?width=1024"},{"name":"Arabian Mau","rarity":"common","id":"arabian-mau","subtitle":"Breed","details":"A desert-tough natural breed of the Arabian Peninsula, built slim and big-eared for the heat.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Arabian%20Mau%20Cat.jpg?width=1024"},{"name":"Brazilian Shorthair","rarity":"common","id":"brazilian-shorthair","subtitle":"Breed","details":"Brazil's sleek street cat turned breed, with a coat like brushed silk and expressive almond eyes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Frida%20dormindo.JPG?width=1024"},{"name":"Ceylon Cat","rarity":"common","id":"ceylon-cat","subtitle":"Breed","details":"A rare, small ticked breed from Sri Lanka, marked with a cobra-like pattern on the back of the neck.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/The%20book%20of%20the%20cat%20%28Plate%20%2812%29%29%20BHL23996607.jpg?width=1024"},{"name":"Chantilly-Tiffany","rarity":"common","id":"chantilly-tiffany","subtitle":"Breed","details":"A chocolate-brown, semi-longhaired charmer once thought extinct, treasured for its soft, quiet chirp.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chantilly-Tiffany%20kitten.jpg?width=1024"},{"name":"Colorpoint Shorthair","rarity":"common","id":"colorpoint-shorthair","subtitle":"Breed","details":"A Siamese-shaped cat pointed in colours the Siamese never wears, from red points to lynx points.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Chocolate%20Tortie%20Pt%2011636-140.jpg?width=1024"},{"name":"Cyprus Cat","rarity":"common","id":"cyprus-cat","subtitle":"Breed","details":"Among the world's oldest domestic cats: a Cyprus burial beside a human dates back some 9,500 years.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cyprus-Cat-Cape-Greco.jpg?width=1024"},{"name":"Dragon Li","rarity":"common","id":"dragon-li","subtitle":"Breed","details":"China's golden-brown mackerel tabby, a natural breed prized for intelligence and a hunter's patience.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dragon%20Li%20Named%20Taiga%2020150829.jpg?width=1024"},{"name":"European Shorthair","rarity":"common","id":"european-shorthair","subtitle":"Breed","details":"The sturdy farm cat of continental Europe, the pedigree form of the classic household mouser.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/European-cat%20show%20Helsinki%202008.JPG?width=1024"},{"name":"Foldex","rarity":"common","id":"foldex","subtitle":"Breed","details":"A Canadian blend of Scottish Fold and Exotic, with folded ears and a round, owl-like face.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cachorro%20de%20Gato%20FoldEx%20%28%22Belisario%20del%20Laberinto%22%29.JPG?width=1024"},{"name":"German Rex","rarity":"common","id":"german-rex","subtitle":"Breed","details":"The oldest curly breed, traced to a wavy-coated cat found near a Berlin hospital in the 1940s.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/German%20rex.jpg?width=1024"},{"name":"Javanese","rarity":"common","id":"javanese","subtitle":"Breed","details":"A long-haired Oriental type with a single silky coat, named for an island it never came from.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Oriental%20Longhair%20%28Javanese%2C%20Mandarin%29%2C%20Red%20Classic%20Tabby.jpg?width=1024"},{"name":"Lambkin","rarity":"common","id":"lambkin","subtitle":"Breed","details":"A cross of Munchkin and Selkirk Rex: short legs wrapped in soft lamb-like curls.","image":"https://fashionhub.decorexpro.com/images/article/orig/2019/04/lambkin-opisanie-porody-kormlenie-i-uhod-1.jpg"},{"name":"Minskin","rarity":"common","id":"minskin","subtitle":"Breed","details":"A short-legged, mostly hairless breed with fur points on the face, ears, legs, and tail.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Minskin%20Kitten%20Female%20blue%20tabby%20color-pattern.jpg?width=1024"},{"name":"Ojos Azules","rarity":"common","id":"ojos-azules","subtitle":"Breed","details":"Spanish for blue eyes: a New Mexico breed whose deep blue eyes appear in cats of any coat colour.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Gatita%20blanca%20con%20ojos%20azules.jpg?width=1024"},{"name":"Raas Cat","rarity":"common","id":"raas-cat","subtitle":"Breed","details":"A sleek Indonesian island breed from Raas, with a kinked tail tip and striking pale eyes.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black%20sepia%20Raas%20cat.jpg?width=1024"},{"name":"Serrade Petit","rarity":"common","id":"serrade-petit","subtitle":"Breed","details":"A tiny French breed, one of the smallest of all cats, with a fine coat and an oversized personality.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Serrade%20petit.jpg?width=1024"},{"name":"Skookum","rarity":"common","id":"skookum","subtitle":"Breed","details":"A curly-coated short-legged breed, the LaPerm meets the Munchkin, named with a Chinook word for strong.","image":"https://www.pictures-of-cats.org/images/skookum.jpg"},{"name":"Sokoke","rarity":"common","id":"sokoke","subtitle":"Breed","details":"A rare natural breed from Kenya's Arabuko Sokoke forest, with a ticked tabby coat like wood grain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sokoke%20dalili.jpg?width=1024"},{"name":"Suphalak","rarity":"common","id":"suphalak","subtitle":"Breed","details":"A rich copper-brown Thai breed described in old cat poems, distinct from the paler Burmese.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/SuphalakAyodia.jpg?width=1024"},{"name":"Thai Cat","rarity":"common","id":"thai-cat","subtitle":"Breed","details":"The old-style Siamese of Thailand, rounder-faced than the modern show Siamese and just as talkative.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/THA-%20Thai%20cat%20%283155071335%29.jpg?width=1024"},{"name":"York Chocolate","rarity":"common","id":"york-chocolate","subtitle":"Breed","details":"A New York farm breed in deep chocolate brown, founded by a long-haired barn cat named Brownie.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Berndie%2011062014%20443.jpg?width=1024"},{"name":"Domestic Longhair","rarity":"common","id":"domestic-longhair","subtitle":"Breed","details":"The flowing-coated moggy: a mixed-ancestry cat whose long fur comes from many breeds' quiet contributions.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Long%20haired%20domestic%20cat.jpg?width=1024"},{"name":"Mink Coat","rarity":"common","id":"mink-coat","subtitle":"Pattern","details":"The Tonkinese middle ground between pointed and solid, with a rich, soft shading across the body.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Red_Tonikinese.jpg?width=1024"},{"name":"Sepia Coat","rarity":"common","id":"sepia-coat","subtitle":"Pattern","details":"The Burmese pattern: solid colour that shades subtly lighter on the belly, warm as polished wood.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Male%20Chocolate%20Burmese%20Cat.jpg?width=1024"},{"name":"Cameo","rarity":"common","id":"cameo","subtitle":"Pattern","details":"Red or cream tipping over a white undercoat, so the cat appears dusted with warm powder.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Red%20silver%20tabby%20cat%20portrait%20%28flickr%204984831661%29.jpg?width=1024"},{"name":"Parti-colour","rarity":"common","id":"parti-colour","subtitle":"Pattern","details":"Any coat combining white with two or more colours, the broad family that calicos belong to.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Parti_av_korgangen_i_Trondhjems_Domkirke_ca._1860.jpg?width=500"},{"name":"Locket","rarity":"common","id":"locket","subtitle":"Pattern","details":"A single small white patch on the chest of an otherwise solid cat, like a pendant on a chain.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20black%20cat%20with%20dab%20of%20white%20paint%20on%20chest.jpg?width=1024"},{"name":"Blaze","rarity":"common","id":"blaze","subtitle":"Pattern","details":"A stripe of white running up the nose and forehead, splitting a coloured mask in two.","image":"https://www.floppycats.com/wp-content/uploads/2012/10/Seal-Mitted-Ragdoll-Cat-with-a-Blaze-Oliver-584x625.jpg"},{"name":"Tipped Coat","rarity":"common","id":"tipped-coat","subtitle":"Pattern","details":"Colour only on the hair tips over a pale undercoat, the family that includes smokes and shaded silvers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Persian_Chinchilla_Black_shaded_kitten_%286823768123%29.jpg?width=1024"},{"name":"Hazel Eyes","rarity":"common","id":"hazel-eyes","subtitle":"Pattern","details":"A shifting blend of green, gold, and brown that seems to change colour with the light.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat_eyes_2007-2.jpg?width=1024"},{"name":"Copper Eyes","rarity":"common","id":"copper-eyes","subtitle":"Pattern","details":"The deepest orange eye colour, prized in British Shorthairs and Persians like polished pennies.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Britishblue.jpg?width=1024"},{"name":"Harlequin","rarity":"common","id":"harlequin","subtitle":"Pattern","details":"Mostly white with a few large coloured patches, a step beyond bicolour toward the Van pattern.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Two_cats%2C_one_with_stripes_and_one_with_white_patches%2C_are_comfortably_curled_up_inside_a_wooden_barrel.jpg?width=1024"},{"name":"Shell Coat","rarity":"common","id":"shell-coat","subtitle":"Pattern","details":"The lightest tipping of all, barely a whisper of colour over white, as if dusted by a shell's blush.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Dilute_tortoiseshell_cat_2.jpg?width=1024"},{"name":"Pointed Paws","rarity":"common","id":"pointed-paws","subtitle":"Pattern","details":"Dark feet against a paler leg, the finishing detail of the colourpoint pattern.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Siamese_cat%2C_modern-style.jpg?width=1024"},{"name":"Whisker Spots","rarity":"common","id":"whisker-spots","subtitle":"Pattern","details":"The dotted grid on a tabby's muzzle where each whisker roots, visible even on solid-coloured cats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Brown%20tabby%20cat%20portrait%20close%20up%2002.jpg?width=1024"},{"name":"Jiji","rarity":"common","id":"jiji","subtitle":"Famous Cat","details":"Kiki's sharp-tongued black companion in the Studio Ghibli classic, part delivery crew, part conscience.","image":"https://i.pinimg.com/474x/d1/b5/f5/d1b5f5c13ec95864f8fea69c4e4f4333.jpg"},{"name":"Crookshanks","rarity":"common","id":"crookshanks","subtitle":"Famous Cat","details":"Hermione's bandy-legged, bottlebrush-tailed ginger cat, cleverer than most of the humans around him.","image":"https://images.ctfassets.net/usf1vwtuqyxm/6YLonbA0JeBoyiOcMqXBHK/d852ee67613d40f78447f7a691301dc3/hermionecrookshankscrop.jpg?w=480"},{"name":"Mrs. Norris","rarity":"common","id":"mrs-norris","subtitle":"Famous Cat","details":"The skeletal, lamp-eyed patrol cat of Hogwarts caretaker Argus Filch, tattle-tale of the corridors.","image":"https://images.ctfassets.net/usf1vwtuqyxm/80COk80OzeIGK4Ysws020/21b4676ab95425a014f0bcd2be3ff868/ArgusFilch_WB_F6_FilchClutchingMrsNorrisInArms_HP6D-06262.jpg?w=1200&fit=fill&f=top"},{"name":"Salem Saberhagen","rarity":"common","id":"salem-saberhagen","subtitle":"Famous Cat","details":"A warlock sentenced to a century as a black cat, dispensing sarcasm from the Spellman household.","image":"https://kinoreporter.ru/wp-content/webp-express/webp-images/uploads/2019/07/salem-the-cat-lede.jpg.webp"},{"name":"The Catbus","rarity":"common","id":"the-catbus","subtitle":"Famous Cat","details":"My Neighbor Totoro's twelve-legged, grinning feline bus, headlights glowing in its enormous eyes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/2020-06-20_Streetart_Catbus.jpg/1280px-2020-06-20_Streetart_Catbus.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Top Cat","rarity":"common","id":"top-cat","subtitle":"Famous Cat","details":"Hanna-Barbera's alley-cat con artist in a vest and hat, always one scheme ahead of Officer Dibble.","image":"https://prod-s.cdn-cf.philo.com/gracenote/assets/p515669_i_v11_ac.jpg?auto=webp&ver=1&width=630"},{"name":"Socks Clinton","rarity":"common","id":"socks-clinton","subtitle":"Famous Cat","details":"The tuxedo cat who lived in the White House through the 1990s and received fan mail by the sackful.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d0/Barbara_Kinney_with_Socks_%28the_Clinton_family_pet_cat%29%2C_the_White_House_in_1993_-_WHPO-P02282_-_DPLA_%28cropped%29.jpg/1280px-Barbara_Kinney_with_Socks_%28the_Clinton_family_pet_cat%29%2C_the_White_House_in_1993_-_WHPO-P02282_-_DPLA_%28cropped%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Choupette","rarity":"common","id":"choupette","subtitle":"Famous Cat","details":"Karl Lagerfeld's blue-eyed Birman, a pampered muse with her own maids, diary, and fashion lines.","image":"https://d3avoj45mekucs.cloudfront.net/astrogempak/media/2019-flavettesglowingstar/t-karl-lagerfeld-choupette.jpg"},{"name":"Waffles the Cat","rarity":"common","id":"waffles-the-cat","subtitle":"Famous Cat","details":"A Scottish Fold whose permanently surprised round face made him one of Instagram's early cat stars.","image":"https://static.boredpanda.com/blog/wp-content/uploads/2014/11/waffles-the-cats__700.jpg"},{"name":"Thurston Waffles","rarity":"common","id":"thurston-waffles","subtitle":"Famous Cat","details":"A white cat whose theatrical, wide-eyed reactions to everyday life made him one of the most beloved meme cats.","image":"https://i.kym-cdn.com/entries/icons/original/000/031/575/waffle.jpg"},{"name":"Crying Cat","rarity":"common","id":"crying-cat","subtitle":"Famous Cat","details":"A digitally tear-eyed cat face expressing every small heartbreak of the internet age at once.","image":"https://www.blowingideas.com/wp-content/uploads/2020/04/The-Crying-Cat-Meme.jpg.webp"},{"name":"Bingus","rarity":"common","id":"bingus","subtitle":"Famous Cat","details":"A wide-eyed, nearly hairless Sphynx whose blank stare became a staple of surreal meme edits.","image":"https://i.pinimg.com/originals/1b/86/c5/1b86c52161d96c3ba690473ff5cb623e.jpg"},{"name":"Beluga Cat","rarity":"common","id":"beluga-cat","subtitle":"Famous Cat","details":"Hecker, the polite white cat of Discord meme fame, always mid-scheme with a knowing smirk.","image":"https://lemmy.world/pictrs/image/ec69b3ba-6298-461c-8af6-e6aefb74e6bd.jpeg"},{"name":"Street Cat Bob","rarity":"common","id":"street-cat-bob","subtitle":"Famous Cat","details":"The ginger cat who adopted a London busker, rode the bus on his shoulder, and inspired a book and film.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Bob_the_Street_Cat_high-fives_his_official_biographer_James_Bowen_on_the_publication_of_their_new_book._%287510771672%29.jpg/1280px-Bob_the_Street_Cat_high-fives_his_official_biographer_James_Bowen_on_the_publication_of_their_new_book._%287510771672%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Oscar the Therapy Cat","rarity":"common","id":"oscar-the-therapy-cat","subtitle":"Famous Cat","details":"A Rhode Island hospice cat famed for curling up beside patients in their final hours, with uncanny timing.","image":"https://story.levanews.com/wp-content/uploads/2024/08/Meet-Oscar-The-Cat-Who-Could-Predict-Death-728x410-1.jpg"},{"name":"Mike the Museum Cat","rarity":"common","id":"mike-the-museum-cat","subtitle":"History","details":"For twenty years this British Museum cat guarded the main gate, famous for pouncing pigeons and ignoring visitors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mike%20the%20Cat%2C%20Guardian%20of%20the%20British%20Museum.png?width=500"},{"name":"Beerbohm the Theatre Cat","rarity":"common","id":"beerbohm-the-theatre-cat","subtitle":"History","details":"A tabby resident of London's Gielgud Theatre, so beloved that his portrait hangs in the building and obituaries marked his passing.","image":"https://imgc.allpostersimages.com/img/posters/frances-broomfield-beerbohm-the-theatre-cat_u-l-q1jhdq7o1zoo.jpg"},{"name":"Churchill's Cats","rarity":"common","id":"churchills-cats","subtitle":"History","details":"Winston Churchill adored cats: Nelson served at Downing Street, and marmalade Jock's descendants still live at Chartwell.","image":"https://www.purr-n-fur.org.uk/featuring/mus/12chartwell-jock7-01.jpg"},{"name":"Mark Twain's Cats","rarity":"common","id":"mark-twains-cats","subtitle":"History","details":"Mark Twain kept cats with names like Apollinaris and Sackcloth, and wrote that a house without one lacked its finest ornament.","image":"https://www.thescroller.net/wp-content/uploads/2025/08/14-5.jpg"},{"name":"Cats of the Trenches","rarity":"common","id":"cats-of-the-trenches","subtitle":"History","details":"Armies of the First World War kept hundreds of thousands of cats in trenches and depots for rats, gas warnings, and morale.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Soldier%20of%20the%20Black%20Watch%20of%20Canada%2C%20holding%20a%20kitten%20%28First%20World%20War%29.jpg?width=500"},{"name":"Towser's Record","rarity":"common","id":"towsers-record","subtitle":"History","details":"A Glenturret distillery cat credited with catching 28,899 mice across a 24-year career, a world record.","image":"https://drammingaround.com/wp-content/uploads/2025/10/img_20250913_111335.jpg?w=768"},{"name":"The Great Fire Cats","rarity":"common","id":"the-great-fire-cats","subtitle":"History","details":"London lore remembers cats among the few creatures who thrived in the ruins after the Great Fire of 1666, hunting the rubble.","image":"https://images.fineartamerica.com/images/artworkimages/medium/3/the-great-fire-of-london-master-art-collection.jpg"},{"name":"Hokusai's Cat Sketches","rarity":"common","id":"hokusais-cat-sketches","subtitle":"Art","details":"The great Japanese master filled sketchbooks with quick, living studies of cats washing, stretching, and sleeping.","image":"https://render.fineartamerica.com/images/images-profile-flow/400/images/artworkimages/mediumlarge/3/a-cat-cleaning-its-claws-by-hokusai-art-anthology-japanese.jpg"},{"name":"Picasso's Cat with a Crab","rarity":"common","id":"picassos-cat-with-a-crab","subtitle":"Art","details":"Picasso painted a cat menacing a crab in 1964, all claws and appetite in a few ferocious strokes.","image":"https://fadmagazine.com/wp-content/uploads/PICAS130139_JE260226-hires-1200x918.jpg"},{"name":"Gauguin's Still Life with Cat","rarity":"common","id":"gauguins-still-life-with-cat","subtitle":"Art","details":"A small cat slips through Gauguin's Tahitian still lifes, part of the furniture of paradise.","image":"https://happywall-img-gallery.imgix.net/154300/paul_gauguin_tahitian_women_with_black_cat_display.jpg?w=600"},{"name":"The Cat Statue of Kuching","rarity":"common","id":"the-cat-statue-of-kuching","subtitle":"Art","details":"Kuching, Malaysia's 'Cat City', keeps giant cat statues downtown, mascots of a name that sounds like the Malay word for cat.","image":"https://mpoprofit-travel.com/wp-content/uploads/2026/02/cats-of-kuching.jpg-768x512.png"},{"name":"Gottfried Mind's Mad Cats","rarity":"common","id":"gottfried-minds-mad-cats","subtitle":"Art","details":"The Swiss 'Cat Raphael' drew almost nothing but cats, producing portraits of uncanny feline character in the 1800s.","image":"https://images.fineartamerica.com/images/artworkimages/mediumlarge/3/white-cat-with-cubs-playing-with-a-mouse-gottfried-mind.jpg"},{"name":"The Wampus Cat","rarity":"common","id":"the-wampus-cat","subtitle":"Mythology","details":"A fearsome cat of Appalachian and Cherokee lore, said to prowl the woods at night with glowing eyes.","image":"https://www.spookyappalachia.com/wp-content/uploads/2024/06/wampuscat-1024x585.jpeg"},{"name":"Cactus Cat","rarity":"common","id":"cactus-cat","subtitle":"Mythology","details":"A tall tale of the American Southwest: a bobcat-like creature with spines that slashes cacti and drinks the sap.","image":"https://s13emagst.akamaized.net/products/68804/68803536/images/res_6c7f4f1c1141fb2946123665fed00f08.jpg?width=720&height=720&hash=5800754F43418D0D06CEB3F7B97F4B16"},{"name":"Nine Lives","rarity":"common","id":"nine-lives","subtitle":"Mythology","details":"The old saying grants cats nine lives for their escapes; in some countries tradition allows only seven.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Falling%20cat%201894.jpg?width=1024"},{"name":"Black Cat Crossing","rarity":"common","id":"black-cat-crossing","subtitle":"Mythology","details":"A black cat crossing your path is doom in some lands and luck in others; British and Japanese tradition mostly say luck.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2026-01-11%20Black%20cat%20walking%20along%20the%20rails%20of%20the%20Nazar%C3%A9%20funicular.jpg?width=1024"},{"name":"Sailors' Lucky Cat","rarity":"common","id":"sailors-lucky-cat","subtitle":"Mythology","details":"Seafarers prized ship's cats as luck itself: a cat sneezing meant rain, and a happy cat promised a fair wind.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Sailors%20surround%20the%20ship%27s%20cat%20%22Convoy%22%20asleep%20in%20a%20miniature%20hammock%20on%20board%20HMS%20HERMIONE%2C%20Gibraltar%2C%2026%20November%201941.%20A6410.jpg?width=1024"},{"name":"Blue Kitten Eyes","rarity":"common","id":"blue-kitten-eyes","subtitle":"Anatomy","details":"Every kitten opens blue eyes at about a week old; the true colour develops over the following months.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ragdoll_Kitten_with_Blue_Eyes_DMNO-28.jpg?width=1024"},{"name":"Purr Apparatus","rarity":"common","id":"purr-apparatus","subtitle":"Anatomy","details":"Rapid muscle twitches in the voice box, driven 25 times a second, build the purr on both breath in and breath out.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black%20cat%20with%20Lymphoma%20being%20pet.png?width=1024"},{"name":"Tail Bones","rarity":"common","id":"tail-bones","subtitle":"Anatomy","details":"The tail carries around a tenth of a cat's bones and works as a counterweight for tightrope walks along fence tops.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Close_up_of_red_cat%27s_tail_flower.jpg?width=500"},{"name":"Scruff","rarity":"common","id":"scruff","subtitle":"Anatomy","details":"The loose skin at the neck is how mother cats carry kittens, who go instinctively limp when it is held.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Mother_Cat_Stops_Traffic_photo_by_Harry_Warnecke.jpg?width=1024"},{"name":"Rough Coat Guard Hairs","rarity":"common","id":"rough-coat-guard-hairs","subtitle":"Anatomy","details":"Long guard hairs form the weatherproof outer layer of the coat, shedding rain over the soft undercoat beneath.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Tabby%20cat%20Fur.jpg?width=1024"},{"name":"Undercoat","rarity":"common","id":"undercoat","subtitle":"Anatomy","details":"A dense layer of fine down hairs traps warm air against the skin, and is the source of most seasonal shedding.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Fluffy_cat._Amir_Temur_Street003.jpg?width=1024"},{"name":"Night Vision","rarity":"common","id":"night-vision","subtitle":"Anatomy","details":"With six to eight times more light-sensitive rod cells than humans, cats hunt comfortably in near darkness.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Eyeshine%20in%20Felis%20catus%20%28domestic%20cat%29%203.jpg?width=1024"},{"name":"Inner Ear Balance","rarity":"common","id":"inner-ear-balance","subtitle":"Anatomy","details":"A vestibular system of exquisite sensitivity tells a cat which way is up, powering leaps, landings, and the righting reflex.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20walking%20on%20a%20wall%20in%20Santorin.JPG?width=1024"},{"name":"Hairball Engineering","rarity":"common","id":"hairball-engineering","subtitle":"Anatomy","details":"Swallowed fur usually passes through; what cannot becomes the infamous hairball, ejected with theatrical sound effects.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Long-haired-cat-hairball.jpg?width=1024"},{"name":"Catnip Receptor","rarity":"common","id":"catnip-receptor","subtitle":"Anatomy","details":"Sensitivity to catnip is inherited: about a third of cats lack the gene response and walk past the plant unimpressed.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Catnip-effects.jpg?width=1024"},{"name":"Whisker Fatigue Lore","rarity":"common","id":"whisker-fatigue-lore","subtitle":"Anatomy","details":"The idea that bowls over-stimulate whiskers is popular lore; what is certain is that whiskers dislike being bent for long.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat_eating_from_a_bowl.jpg?width=1024"},{"name":"Belly Fur Primordial Guard","rarity":"common","id":"belly-fur-primordial-guard","subtitle":"Anatomy","details":"The belly is a cat's most guarded zone: showing it signals trust, but it is a display, not an invitation.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%27s_belly_in_sunlight.jpg?width=1024"},{"name":"Grooming Rituals","rarity":"common","id":"grooming-rituals","subtitle":"Behavior","details":"Cats spend up to a third of waking life washing, spreading skin oils and scents in a precise, practised order.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20cat%20grooming%20%288630065306%29.jpg?width=1024"},{"name":"Allogrooming","rarity":"common","id":"allogrooming","subtitle":"Behavior","details":"Cats who wash each other are declaring alliance; shared grooming is one of the clearest signs of a feline friendship.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Two%20European%20Shorthairs.jpg?width=1024"},{"name":"Scratching Posts","rarity":"common","id":"scratching-posts","subtitle":"Behavior","details":"Scratching sheds old claw sheaths, stretches the back, and leaves both a visible sign and a scent signature.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Corrugated%20fiberboard%20scratch%20pad%20with%20cat.jpg?width=1024"},{"name":"Sunbathing","rarity":"common","id":"sunbathing","subtitle":"Behavior","details":"A cat in a sunbeam saves energy on body heat and tops up oils in the coat, and will follow the patch all afternoon.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20sunbathing.jpg?width=1024"},{"name":"Staring Contests","rarity":"common","id":"staring-contests","subtitle":"Behavior","details":"An unbroken stare is a challenge among cats, but a soft gaze with slow blinks is an invitation to relax together.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cats%20Jip%20and%20Noah%20communicating%2028022008%28004%29.jpg?width=1024"},{"name":"Trilling","rarity":"common","id":"trilling","subtitle":"Behavior","details":"The closed-mouth chirrup is a mother's call to kittens, kept for greeting favourite humans at the door.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20is%20sitting%20on%20the%20wall.jpg?width=1024"},{"name":"The Paw Reach","rarity":"common","id":"the-paw-reach","subtitle":"Behavior","details":"A single paw extended under doors, through gaps, and toward anything interesting just out of range.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20Paws%20Under%20Door%201%202014-11-08.JPG?width=1024"},{"name":"Hissing","rarity":"common","id":"hissing","subtitle":"Behavior","details":"A hiss is a warning, not an attack: the feline equivalent of a firm request for immediate personal space.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hissing%20cats.jpg?width=1024"},{"name":"Midnight Yowling","rarity":"common","id":"midnight-yowling","subtitle":"Behavior","details":"The caterwaul carries astonishing distances, used for territory, courtship, and occasionally, sheer commentary.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Black-and-white%20cat%20with%20open%20mouth%20and%20belled%20collar.jpg?width=1024"},{"name":"Hiding in Bags","rarity":"common","id":"hiding-in-bags","subtitle":"Behavior","details":"A paper bag is cover, ambush post, and acoustic toy in one; the rustle is half the attraction.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%A4mu%20the%20cat%20in%20paper%20bag.jpg?width=1024"},{"name":"Cardboard Over Cat Beds","rarity":"common","id":"cardboard-over-cat-beds","subtitle":"Behavior","details":"Given a costly bed and a free box, cats reliably choose the box: tight, warm, and smelling of adventure.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cats%20in%20cardboard%20boxes%20Philippines.jpg?width=1024"},{"name":"Paw Dipping","rarity":"common","id":"paw-dipping","subtitle":"Behavior","details":"Some cats scoop water with a paw rather than drink directly, testing depth and freshness like their wild ancestors.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Boo%20Boo%20%28ca%201960%20%29%20%287851200822%29.jpg?width=1024"},{"name":"Weaving Between Legs","rarity":"common","id":"weaving-between-legs","subtitle":"Behavior","details":"Cats wind figure-eights around their people's ankles: part greeting, part scent-marking, part trip hazard.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Meow.love.jpg?width=1024"},{"name":"Monastery Cats","rarity":"common","id":"monastery-cats","subtitle":"Working Cat","details":"Monks have kept cats for manuscripts' sake since the Middle Ages; a 9th-century poem to a cat survives from one.","image":"https://irp.cdn-website.com/d2942488/dms3rep/multi/opt/2Z6A9137-1920w.jpg"},{"name":"Temple Cats","rarity":"common","id":"temple-cats","subtitle":"Working Cat","details":"Bangkok and Kyoto temples keep colonies of cats fed by monks, guardians in the courtyards of the sacred.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20sleeping%20in%20the%20Ng%E1%BB%8Dc%20S%C6%A1n%20Temple%20in%20Hanoi%2C%2020240204%201309%205747.jpg?width=1024"},{"name":"Greenhouse Cats","rarity":"common","id":"greenhouse-cats","subtitle":"Working Cat","details":"Garden centres and nurseries employ cats to patrol the plants, and customers come as much for them as the flowers.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20in%20greenhouse%20%28284812343%29.jpg?width=1024"},{"name":"Warehouse Cats","rarity":"common","id":"warehouse-cats","subtitle":"Working Cat","details":"Working-cat programmes place unsocialised cats in warehouses, where their scent alone deters rodents.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20guards%20of%20Spice%20warehouse..JPG?width=1024"},{"name":"Museum Cats","rarity":"common","id":"museum-cats","subtitle":"Working Cat","details":"From the Hermitage onward, museums quietly employ cats as the oldest form of collection pest management.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hermitage%20cat.jpeg?width=1024"},{"name":"Post Office Cats","rarity":"common","id":"post-office-cats","subtitle":"Working Cat","details":"Victorian Britain officially employed post office cats on a wage of a shilling a week for mouse duty.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Feline%20presence%20at%20the%20post%20office%20-%20geograph.org.uk%20-%20626098.jpg?width=1024"},{"name":"Prison Cats","rarity":"common","id":"prison-cats","subtitle":"Working Cat","details":"Some prisons run cat programmes where inmates foster shelter cats, teaching care skills and calming whole wings.","image":"https://www.totallyveganbuzz.com/wp-content/uploads/2019/10/Rescue-cats-transform-inmates-lives-at-prison-in-Indiana_TotallyVeganBuzz_7-687x512-1.jpg"},{"name":"Railway Cats","rarity":"common","id":"railway-cats","subtitle":"Working Cat","details":"Beyond Japan's stationmasters, railways worldwide have kept platform cats as pest controllers and mascots.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/A%20sitting%20red%20tabby%20cat%20on%20platform%20at%20Shifen%20Railway%20Station%2020170429%20%282017%3B%20cropped%202025%29.jpg?width=1024"},{"name":"Market Cats","rarity":"common","id":"market-cats","subtitle":"Working Cat","details":"From Istanbul bazaars to Mexican mercados, market cats hold hereditary stalls of their own among the produce.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20at%20fish%20market%2C%20Naples.jpg?width=1024"},{"name":"Castle Cats","rarity":"common","id":"castle-cats","subtitle":"Working Cat","details":"Castles and stately homes keep cats as they always have: quiet professionals guarding stores and stables.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Castle%20Cat%20%28201760309%29.jpeg?width=1024"},{"name":"Winery Cats","rarity":"common","id":"winery-cats","subtitle":"Working Cat","details":"Vineyard cats patrol barrel halls and tasting rooms, and often end up on the label photography.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Winery%20Cat%20Rotta%20Winery.jpg?width=1024"},{"name":"Church Cats","rarity":"common","id":"church-cats","subtitle":"Working Cat","details":"Churches keep cats for the mice in the vestry and the calm in the nave; some earn a mention in the parish magazine.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hodge,%20Southwark%20Cathedral's%20Cat%20-%202024-08-04.jpg?width=1024"},{"name":"Office Cats","rarity":"common","id":"office-cats","subtitle":"Working Cat","details":"Modern offices adopt resident cats for morale; some firms formally assign them departments and titles.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Office%20cat%20%28Oct%202020%29%201.jpg?width=1024"},{"name":"Fishing Boat Cats","rarity":"common","id":"fishing-boat-cats","subtitle":"Working Cat","details":"Harbour and fishing cats ride out for the catch and are traditionally paid first, in fish, at the dock.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20on%20a%20Fishing%20boat%20canoe%20on%20Chivla%20beach%20in%20Malvan..JPG?width=1024"},{"name":"Lighthouse Cats","rarity":"common","id":"lighthouse-cats","subtitle":"Working Cat","details":"Keepers' cats were common at remote lights, company for families and hunters of the stores' rats.","image":"https://azure.wgp-cdn.co.uk/app-yourcat/posts/lighthouse3.jpg"},{"name":"Zoo Cats","rarity":"common","id":"zoo-cats","subtitle":"Working Cat","details":"Some zoos keep barn cats around feed stores, the one animal on site officially there to hunt the others' pests.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cat%20sitting%20on%20a%20ledge%20at%20zoo.jpg?width=1024"},{"name":"Manabeshima Cats","rarity":"common","id":"manabeshima-cats","subtitle":"Cat Place","details":"A small Okayama fishing island whose cat population stars in films and draws quiet tourism.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/%E5%A4%8F%E3%81%AE%E7%9C%9F%E9%8D%8B%E5%B3%B6%E6%9C%AC%E6%B5%A6%E6%B8%AF.jpg?width=500"},{"name":"Genkaishima Cats","rarity":"common","id":"genkaishima-cats","subtitle":"Cat Place","details":"A Fukuoka island where cats gather at the harbour each morning to supervise the fishing fleet's return.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Genkaiisland.port.passenger%20waiting%20area.jpg?width=1024"},{"name":"Sanagijima Cats","rarity":"common","id":"sanagijima-cats","subtitle":"Cat Place","details":"A Kagawa island photographed for its cats leaping between harbour walls and napping on the breakwater.","image":"https://visitjapan-vegetarian.com/wp-content/uploads/2022/04/Cats-on-Sanagi-Island-Jumping-between-Disconnected-Embarkments-Nakatado-Kagawa-Japan.jpg"},{"name":"Muzushima and Ao Cats","rarity":"common","id":"muzushima-and-ao-cats","subtitle":"Cat Place","details":"Tiny island communities in the Seto Inland Sea where cats are simply part of the village census.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cats%20in%20Ogijima.jpg?width=1024"},{"name":"Kalkan's Cats","rarity":"common","id":"kalkans-cats","subtitle":"Cat Place","details":"The Turkish harbour town where a local charity feeds, neuters, and shelters a famous population of street cats.","image":"https://thesunlounger.co.uk/wp-content/uploads/2026/01/c1.png"},{"name":"Greek Island Cats","rarity":"common","id":"greek-island-cats","subtitle":"Cat Place","details":"Across the Aegean, harbour cats wait by the fishing boats, an institution as old as the islands' villages.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hydra-island-cats-2022.jpg?width=1024"},{"name":"The Colosseum Cats","rarity":"common","id":"the-colosseum-cats","subtitle":"Cat Place","details":"Rome's famous ruin hosts a protected feral colony, looked after by volunteers among two thousand years of stone.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Rome%20Colosseum%20Feral%20Cat.jpg?width=1024"},{"name":"Brooklyn's Bodega Cats","rarity":"common","id":"brooklyns-bodega-cats","subtitle":"Cat Place","details":"New York's corner stores keep beloved bodega cats, technically rule-breakers and practically civic treasures.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bodega%20cat%20at%20Heavenly%20Market%20IV%2C%201760%203rd%20Avenue%2C%202024-06-27%2C%20East%20Harlem%2C%20Manhattan%2C%20New%20York%2005.jpg?width=1024"},{"name":"The Algonquin Hotel","rarity":"common","id":"the-algonquin-hotel","subtitle":"Cat Place","details":"The Manhattan hotel whose resident cat tradition runs from Hamlet to Matilda, with a chair and email of their own.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/TheAlgonquin.JPG?width=1024"},{"name":"Lady Dinah's Cat Emporium","rarity":"common","id":"lady-dinahs-cat-emporium","subtitle":"Cat Place","details":"London's first cat cafe, opened in 2014 after a crowdfunding campaign, pairing tea with rescue cats.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Lady%20Dinah%27s%20Cat%20Emporium%202024-06-16.jpg?width=1024"},{"name":"Houtong Cat Village","rarity":"common","id":"houtong-cat-village","subtitle":"Cat Place","details":"A Taiwan mining village reinvented by its cats, with cat cafes, a cat bridge, and hundreds of cared-for residents.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/2015-05-03%20rules%20in%20the%20Houtong%20Cat%20Village.jpg?width=1024"},{"name":"Bubastis, City of Bastet","rarity":"common","id":"bubastis-city-of-bastet","subtitle":"Cat Place","details":"The Nile Delta city of the cat goddess, where vast cemeteries of mummified cats surrounded her great temple.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Bubastis%20012.JPG?width=1024"},{"name":"A Cat Colony (TNR)","rarity":"common","id":"a-cat-colony-tnr","subtitle":"Cat Place","details":"Managed feral colonies, trapped, neutered, and returned, are cared for by feeders who know every ear-tip by name.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Messina%20cat%20colony%202-11-20.jpg?width=1024"}]});
